            jobs.push({ name: '🐴 Stablehand', hours: 8, pay: Math.round(4 * payScale), ticks: 20, type: 'odd', xpReward: 1, description: 'Tend to horses and mules' });
            // Tavern Entertainer — available in any town, instrument-based
            var _tavEntPay = getEntertainmentPayMultiplier(town.id);
