    function assassinatePassenger(passengerIndex) {
        if (!player.activeTransport) return { success: false, message: 'No active transport.' };
        if (!hasSkill('assassin') && !hasSkill('dark_connections')) return { success: false, message: 'Requires Assassin or Dark Connections skill.' };
        var transport = player.activeTransport;
        if (!transport.passengers || !transport.passengers[passengerIndex]) return { success: false, message: 'Invalid passenger.' };
        var passenger = transport.passengers[passengerIndex];

        var person = Engine.findPerson ? Engine.findPerson(passenger.personId) : null;
        if (!person || !person.isEliteMerchant) return { success: false, message: 'Target is not an elite merchant.' };

        // High risk — 30% base detection
        var detection = 0.30;
        if (hasSkill('assassin')) detection *= 0.5;
        if (hasSkill('poisoner')) detection *= 0.7;
        var rng = Engine.getRng();

        if (rng && rng.chance(detection)) {
            // Caught! Severe punishment
            player.notoriety = (player.notoriety || 0) + 30;
            var town = Engine.findTown(player.townId);
            var kingdom = town ? (Engine.findKingdom ? Engine.findKingdom(town.kingdomId) : null) : null;
            applyCorruptPenalty(town, kingdom, 5000, 50, 30, true);
            recordCorruptAction('assassinate_passenger', true);
            // Remove all passengers — they flee
            transport.passengers = [];
            Engine.logEvent(player.fullName + ' was caught attempting to assassinate ' + person.firstName + '!');
            return { success: false, caught: true, message: '\uD83D\uDEA8 CAUGHT! Massive fine, jailed 30 days, reputation destroyed.' };
        }

        // Success — kill the merchant
        if (Engine.killPerson) Engine.killPerson(person, 'assassination');
        player.notoriety = (player.notoriety || 0) + 15;
        recordCorruptAction('assassinate_passenger', false);
        grantXP(50, 'Assassination');

        // Remove from passenger list
        transport.passengers.splice(passengerIndex, 1);
        transport.totalRevenue = (transport.totalRevenue || 0) - (passenger.fare || 0);

        // Loot their gold
        var loot = Math.floor((person.gold || 0) * 0.5);
        player.gold += loot;

        Engine.logEvent('An elite merchant was found dead during transport. Foul play suspected.');
        return { success: true, message: '\u2620\uFE0F ' + person.firstName + ' eliminated. Looted ' + loot + 'g. Their empire will pass to an heir... or collapse.' };
    }

    function executeCorruptAction(actionId, params) {
        switch (actionId) {
            case 'sabotage_building': return sabotageBuilding(params[0], params[1]);
            case 'sabotage_road': return sabotageRoad(params[0]);
            case 'arson': return commitArson(params[0], params[1]);
            case 'steal_goods': return stealGoods(params[0], params[1], params[2]);
            case 'pickpocket': return pickpocket(params[0]);
            case 'warehouse_heist': return warehouseHeist(params[0]);
            case 'rob_traveler': return robTraveler(params[0]);
            case 'raid_caravan': return raidCaravan(params[0]);
            case 'counterfeit': return sellCounterfeit(params[0], params[1], params[2]);
            case 'bribe_guards': return bribeGuards(params[0], params[1]);
            case 'bribe_advisor': return bribeAdvisor(params[0], params[1]);
            case 'cultivate_heir': return cultivateHeir(params[0]);
            case 'blackmail': return blackmailNPC(params[0]);
            case 'spread_rumors': return spreadRumors(params[0]);
            case 'frame_competitor': return frameCompetitor(params[0], params[1]);
            case 'assassinate_competitor':
            case 'assassinate_guard_captain':
            case 'assassinate_king':
                return hireAssassin(params[0], params[1]);
            case 'assassinate_passenger': return assassinatePassenger(params[0]);
            case 'poison': return poisonTarget(params[0]);
            case 'hidden_warehouse': return buildHiddenWarehouse(params[0]);
            case 'cook_books': return cookTheBooks();
            case 'insider_trading': return insiderTrading(params[0]);
            default: return { success: false, message: 'Unknown action.' };
        }
    }

    function shouldShowSchemesButton() {
        return true; // Always show — player discovers dark deeds exist
    }

    // ========================================================
    // §12H  HOUSING SYSTEM
    // ========================================================
    let _nextHouseId = 1;
    function houseUid() { return 'house_' + (_nextHouseId++); }

    // Get the player's best housing disease reduction (from primary house or best house in current town)
    function getHousingDiseaseReduction() {
        if (!player.houses || player.houses.length === 0) return 0;
        var bestReduction = 0;
        for (var i = 0; i < player.houses.length; i++) {
            var h = player.houses[i];
            if (h.townId !== player.townId) continue;
            var ht = CONFIG.HOUSING_TYPES.find(function(x) { return x.id === h.type; });
            if (ht && ht.diseaseReduction > bestReduction) bestReduction = ht.diseaseReduction;
        }
        return bestReduction;
    }

    function getHousingCost(housingTypeId, townId) {
        const ht = CONFIG.HOUSING_TYPES.find(h => h.id === housingTypeId);
        if (!ht) return { total: 0, materialCost: 0, laborCost: 0, breakdown: {}, available: false, reason: 'Unknown housing type' };

        // Non-constructed items (bedroll, inn_room) use flat cost
        if (ht.cost !== undefined && !ht.materials) {
            return { total: ht.cost, materialCost: ht.cost, laborCost: 0, breakdown: {}, available: true };
        }

        const town = Engine.findTown(townId);
        if (!town) return { total: 0, materialCost: 0, laborCost: 0, breakdown: {}, available: false, reason: 'Town not found' };

        const cat = town.category || 'town';
        const laborMult = (CONFIG.HOUSING_LABOR_MULTIPLIER && CONFIG.HOUSING_LABOR_MULTIPLIER[cat]) || 1.0;
        const laborCost = Math.floor((ht.laborCost || 0) * laborMult);

        if (!ht.materials) {
            // Legacy fallback: flat baseCost if somehow no materials defined
            var baseCost = ht.baseCost || 0;
            return { total: baseCost + laborCost, materialCost: baseCost, laborCost: laborCost, breakdown: {}, available: true };
        }

        // Calculate material cost from local market prices + check availability
        var materialCost = 0;
        var breakdown = {};
        var allAvailable = true;
        var missingItems = [];
        var inv = player.inventory || {};

        // Also check player warehouses in this town
        var warehouseInv = {};
        if (player.hiddenWarehouses) {
            for (var wi = 0; wi < player.hiddenWarehouses.length; wi++) {
                var wh = player.hiddenWarehouses[wi];
                if (wh.townId === townId && wh.inventory) {
                    for (var wk in wh.inventory) {
                        warehouseInv[wk] = (warehouseInv[wk] || 0) + (wh.inventory[wk] || 0);
                    }
                }
            }
        }
        // Also check house storage in this town
        if (player.houses) {
            for (var hi = 0; hi < player.houses.length; hi++) {
                var h = player.houses[hi];
                if (h.townId === townId && h.homeStorage) {
                    for (var hk in h.homeStorage) {
                        warehouseInv[hk] = (warehouseInv[hk] || 0) + (h.homeStorage[hk] || 0);
                    }
                }
            }
        }

        for (var matId in ht.materials) {
            var qtyNeeded = ht.materials[matId];
            var playerHas = (inv[matId] || 0) + (warehouseInv[matId] || 0);
            var needToBuy = Math.max(0, qtyNeeded - playerHas);
            var marketHas = (town.market && town.market.supply[matId]) || 0;
            var marketPrice = 0;

            // Get local market price for this material
            try { marketPrice = Engine.getMarketPrice(townId, matId) || 0; } catch(e) {}
            if (marketPrice <= 0) {
                var res = findResource(matId);
                marketPrice = res ? (res.basePrice || 5) : 5;
            }

            var costForThisMat = needToBuy * marketPrice;
            materialCost += costForThisMat;
            breakdown[matId] = { needed: qtyNeeded, playerHas: playerHas, needToBuy: needToBuy, marketHas: marketHas, unitPrice: marketPrice, subtotal: costForThisMat };

            if (needToBuy > marketHas) {
                allAvailable = false;
                var resInfo = findResource(matId);
                missingItems.push((resInfo ? resInfo.name : matId) + ': need ' + needToBuy + ', market has ' + marketHas);
            }
        }

        var total = materialCost + laborCost;
        return {
            total: total,
            materialCost: materialCost,
            laborCost: laborCost,
            breakdown: breakdown,
            available: allAvailable,
            missingItems: missingItems,
            reason: allAvailable ? null : 'Missing materials: ' + missingItems.join('; ')
        };
    }

    function buyHouse(housingTypeId, townId) {
        if (isJailed()) return { success: false, message: 'You are in jail.' };
        if (player.indentured && player.indentured.active) return { success: false, message: 'Indentured servants cannot own property. Earn your freedom first.' };
        const ht = CONFIG.HOUSING_TYPES.find(h => h.id === housingTypeId);
        if (!ht) return { success: false, message: 'Unknown housing type.' };
        const town = Engine.findTown(townId);
        if (!town) return { success: false, message: 'Town not found.' };

        // Immigration policy enforcement — closed borders block foreign property purchase (except inn/bedroll)
        if (housingTypeId !== 'inn_room' && housingTypeId !== 'bedroll' && town.kingdomId && player.citizenshipKingdomId !== town.kingdomId) {
            var kingdom = Engine.findKingdom(town.kingdomId);
            if (kingdom && hasSpecialLaw(kingdom, 'immigration_policy') && kingdom.immigrationPolicy === 'closed') {
                return { success: false, message: '🚫 ' + kingdom.name + ' has closed borders. Non-citizens cannot buy property. Earn citizenship first.' };
            }
        }

        // Check town category requirement
        if (ht.minTownCategory) {
            const catOrder = ['village', 'town', 'city', 'capital_city'];
            const townCatIdx = catOrder.indexOf(town.category || 'village');
            const reqCatIdx = catOrder.indexOf(ht.minTownCategory);
            if (townCatIdx < reqCatIdx) return { success: false, message: 'Town too small for this housing type. Requires ' + ht.minTownCategory + '.' };
        }
        if (ht.requiresPort && !town.isPort) return { success: false, message: 'Requires a port town.' };

        // Inn rooms and bedrolls are rented/purchased as items, not constructed
        if (ht.id === 'inn_room' || ht.id === 'bedroll') return { success: false, message: 'This housing type cannot be purchased.' };

        // Rank requirement for high-end housing
        if (ht.minRank) {
            var highestRank = 0;
            for (var kId in player.socialRank) { if ((player.socialRank[kId] || 0) > highestRank) highestRank = player.socialRank[kId]; }
            if (highestRank < ht.minRank) {
                var reqRankName = CONFIG.SOCIAL_RANKS[ht.minRank] ? CONFIG.SOCIAL_RANKS[ht.minRank].name : ('Rank ' + ht.minRank);
                return { success: false, message: 'Requires ' + reqRankName + ' rank or higher to build a ' + ht.name + '.' };
            }
        }

        // Caravan wagon doesn't need land
        // Apartments don't need land (they come from apartment buildings)
        if (ht.id !== 'apartment' && !ht.portable && !ht.fromApartmentBuilding) {
            var ownedLand = (player.landOwned && player.landOwned[townId]) || 0;
            var usedLand = getUsedLandSlots(townId);
            var neededSlots = ht.landSlots || 1;
            if (usedLand + neededSlots > ownedLand) {
                return { success: false, message: 'Not enough land. Need ' + neededSlots + ' plot(s) but only ' + Math.max(0, ownedLand - usedLand) + ' available. Buy more land.' };
            }
        }

        // Caravan wagon requires a horse
        if (ht.requiresHorse && (!player.horses || player.horses.length === 0)) {
            return { success: false, message: 'A caravan wagon requires a horse. Buy a horse first.' };
        }

        // ── Dynamic material-based cost calculation ──
        var costInfo = getHousingCost(housingTypeId, townId);

        // Check materials are available
        if (!costInfo.available) {
            return { success: false, message: '🏗️ Cannot build — ' + costInfo.reason };
        }

        // Apply builder skill discounts to labor cost
        var laborCost = costInfo.laborCost;
        if (hasSkill('master_builder')) laborCost = Math.floor(laborCost * 0.80);
        else if (hasSkill('efficient_builder')) laborCost = Math.floor(laborCost * 0.90);

        var totalGoldNeeded = costInfo.materialCost + laborCost;
        if (player.gold < totalGoldNeeded) {
            return { success: false, message: 'Not enough gold. Need ' + totalGoldNeeded + 'g (materials: ' + costInfo.materialCost + 'g + labor: ' + laborCost + 'g). You have ' + Math.floor(player.gold) + 'g.' };
        }

        // ── Consume materials: player inventory/warehouses first, then buy from market ──
        if (ht.materials) {
            for (var matId in ht.materials) {
                var qtyNeeded = ht.materials[matId];
                var remaining = qtyNeeded;

                // Take from player inventory first
                var fromInv = Math.min(player.inventory[matId] || 0, remaining);
                if (fromInv > 0) {
                    player.inventory[matId] -= fromInv;
                    if (player.inventory[matId] <= 0) delete player.inventory[matId];
                    remaining -= fromInv;
                }

                // Take from warehouses in this town
                if (remaining > 0 && player.hiddenWarehouses) {
                    for (var wi = 0; wi < player.hiddenWarehouses.length && remaining > 0; wi++) {
                        var wh = player.hiddenWarehouses[wi];
                        if (wh.townId === townId && wh.inventory && wh.inventory[matId] > 0) {
                            var fromWh = Math.min(wh.inventory[matId], remaining);
                            wh.inventory[matId] -= fromWh;
                            if (wh.inventory[matId] <= 0) delete wh.inventory[matId];
                            remaining -= fromWh;
                        }
                    }
                }

                // Take from house storage in this town
                if (remaining > 0 && player.houses) {
                    for (var hi = 0; hi < player.houses.length && remaining > 0; hi++) {
                        var existingH = player.houses[hi];
                        if (existingH.townId === townId && existingH.homeStorage && existingH.homeStorage[matId] > 0) {
                            var fromHs = Math.min(existingH.homeStorage[matId], remaining);
                            existingH.homeStorage[matId] -= fromHs;
                            if (existingH.homeStorage[matId] <= 0) delete existingH.homeStorage[matId];
                            remaining -= fromHs;
                        }
                    }
                }

                // Buy remainder from town market (gold already accounted for in costInfo)
                if (remaining > 0) {
                    town.market.supply[matId] = Math.max(0, (town.market.supply[matId] || 0) - remaining);
                }
            }
        }

        // Charge gold (material purchase cost + labor)
        player.gold -= totalGoldNeeded;
        logFinance(-totalGoldNeeded, 'housing', 'Bought house');
        player.stats.totalGoldSpent += totalGoldNeeded;

        var house = { id: houseUid(), type: housingTypeId, townId: townId, purchaseDay: Engine.getDay(), occupants: [], homeStorage: {}, isRental: false, rentAccumulated: 0, purchaseCost: totalGoldNeeded, condition: 'new', builtDay: Engine.getDay(), lastRepairDay: 0 };
        if (!player.houses) player.houses = [];
        player.houses.push(house);
        if (!player.primaryHouseId) player.primaryHouseId = house.id;

        // Reputation bonus
        if (ht.repBonus) {
            player.townReputation = player.townReputation || {};
            player.townReputation[townId] = Math.min(100, (player.townReputation[townId] || 0) + ht.repBonus);
        }

        if (typeof Game !== 'undefined' && Game.advanceTicks) Game.advanceTicks(5);
        Engine.logEvent('🏗️ ' + player.fullName + ' built a ' + ht.name + ' in ' + town.name + ' (materials: ' + costInfo.materialCost + 'g, labor: ' + laborCost + 'g).');
        grantXP(5, 'build house');

        // Journal — housing construction
        recordJournalEntry('building', 'Built a ' + ht.name + ' in ' + town.name + ' for ' + totalGoldNeeded + 'g. A proper roof over my head is worth every coin.', { mood: 'hopeful' });

        return { success: true, message: '🏗️ Built ' + ht.name + ' for ' + totalGoldNeeded + 'g (materials: ' + costInfo.materialCost + 'g + labor: ' + laborCost + 'g)!', house: house, costBreakdown: costInfo };
    }

    function sellHouse(houseId) {
        if (!player.houses) return { success: false, message: 'No houses owned.' };
        var idx = player.houses.findIndex(h => h.id === houseId);
        if (idx === -1) return { success: false, message: 'House not found.' };
        var house = player.houses[idx];
        var ht = CONFIG.HOUSING_TYPES.find(h => h.id === house.type);
        // Sell price is based on material value at current market prices × sell ratio
        var costInfo = getHousingCost(house.type, house.townId);
        var sellPrice = Math.floor(costInfo.total * CONFIG.HOUSING_SELL_RATIO);
        // Minimum sell price of the original purchase cost × sell ratio
        if (house.purchaseCost && Math.floor(house.purchaseCost * CONFIG.HOUSING_SELL_RATIO) > sellPrice) {
            sellPrice = Math.floor(house.purchaseCost * CONFIG.HOUSING_SELL_RATIO);
        }
        player.gold += sellPrice;
        player.stats.totalGoldEarned += sellPrice;
        player.houses.splice(idx, 1);
        if (player.primaryHouseId === houseId) {
            var nextHome = player.houses.find(function(h) { return !h.isRental; });
            player.primaryHouseId = nextHome ? nextHome.id : null;
        }
        var town = Engine.findTown(house.townId);
        Engine.logEvent(player.fullName + ' sold a ' + (ht ? ht.name : 'house') + ' in ' + (town ? town.name : 'unknown') + ' for ' + sellPrice + 'g.');
        return { success: true, message: 'Sold for ' + sellPrice + 'g.', amount: sellPrice };
    }

    // ── Leave tent (stop renting) — frees up the tent slot ──
    function leaveTent(houseId) {
        if (!player.houses) return { success: false, message: 'No houses owned.' };
        var idx = player.houses.findIndex(function(h) { return h.id === houseId; });
        if (idx === -1) return { success: false, message: 'Tent not found.' };
        var house = player.houses[idx];
        if (house.type !== 'tent') return { success: false, message: 'This is not a tent.' };

        // Free the tent slot in the camp building
        var town = Engine.findTown(house.townId);
        if (town && house.fromTentCamp != null) {
            var camp = (town.buildings || []).find(function(b) { return b._id === house.fromTentCamp && b.type === 'tent_camp'; });
            if (camp && camp.tents) {
                var slot = camp.tents.find(function(t) { return t.tentIndex === house.tentIndex; });
                if (slot) {
                    slot.occupantId = null;
                    slot.occupantType = null;
                    slot.rentStartDay = null;
                    slot.lastRentDay = null;
                }
            }
        }

        // Remove from player houses
        player.houses.splice(idx, 1);
        if (player.primaryHouseId === houseId) {
            var nextHome = player.houses.find(function(h) { return !h.isRental; });
            player.primaryHouseId = nextHome ? nextHome.id : null;
        }
        player.houseType = null;
        player._tentCampId = null;
        player._tentIndex = null;

        Engine.logEvent('⛺ ' + player.fullName + ' left their tent in ' + (town ? town.name : 'unknown') + '.');
        return { success: true, message: 'You left the tent. It is now available for others.' };
    }

    // ── Housing upgrade (in-place) — pay difference in materials + labor ──
    function upgradeHouse(houseId, newTypeId) {
        if (!player.houses) return { success: false, message: 'No houses owned.' };
        var houseIdx = player.houses.findIndex(h => h.id === houseId);
        if (houseIdx === -1) return { success: false, message: 'House not found.' };
        var house = player.houses[houseIdx];
        var oldHt = CONFIG.HOUSING_TYPES.find(h => h.id === house.type);
        var newHt = CONFIG.HOUSING_TYPES.find(h => h.id === newTypeId);
        if (!oldHt || !newHt) return { success: false, message: 'Unknown housing type.' };
        if (!newHt.materials) return { success: false, message: 'Cannot upgrade to this type.' };

        // Can't downgrade
        var oldCostInfo = getHousingCost(house.type, house.townId);
        var newCostInfo = getHousingCost(newTypeId, house.townId);
        if (newCostInfo.total <= oldCostInfo.total) return { success: false, message: 'Can only upgrade to a more expensive housing type. Sell and rebuild instead.' };

        if (!newCostInfo.available) return { success: false, message: '🏗️ Cannot upgrade — ' + newCostInfo.reason };

        // Credit: recover a portion of old materials value
        var discount = CONFIG.HOUSING_UPGRADE_DISCOUNT || 0.60;
        var credit = Math.floor(oldCostInfo.total * discount);
        var upgradeCost = Math.max(0, newCostInfo.total - credit);

        if (player.gold < upgradeCost) return { success: false, message: 'Need ' + upgradeCost + 'g for upgrade (full cost ' + newCostInfo.total + 'g - ' + credit + 'g credit). You have ' + Math.floor(player.gold) + 'g.' };

        // Check rank for new type
        if (newHt.minRank) {
            var highestRank = 0;
            for (var kId in player.socialRank) { if ((player.socialRank[kId] || 0) > highestRank) highestRank = player.socialRank[kId]; }
            if (highestRank < newHt.minRank) {
                var reqRankName = CONFIG.SOCIAL_RANKS[newHt.minRank] ? CONFIG.SOCIAL_RANKS[newHt.minRank].name : ('Rank ' + newHt.minRank);
                return { success: false, message: 'Requires ' + reqRankName + ' rank for ' + newHt.name + '.' };
            }
        }

        // Consume materials for new house from player/market
        var town = Engine.findTown(house.townId);
        if (newHt.materials && town) {
            for (var matId in newHt.materials) {
                var qtyNeeded = newHt.materials[matId];
                var remaining = qtyNeeded;
                var fromInv = Math.min(player.inventory[matId] || 0, remaining);
                if (fromInv > 0) { player.inventory[matId] -= fromInv; if (player.inventory[matId] <= 0) delete player.inventory[matId]; remaining -= fromInv; }
                if (remaining > 0) { town.market.supply[matId] = Math.max(0, (town.market.supply[matId] || 0) - remaining); }
            }
        }

        player.gold -= upgradeCost;
        player.stats.totalGoldSpent += upgradeCost;

        // Upgrade in place — keep same id, townId, occupants
        house.type = newTypeId;
        house.purchaseCost = (house.purchaseCost || 0) + upgradeCost;

        // New rep bonus
        if (newHt.repBonus && oldHt) {
            var repDiff = (newHt.repBonus || 0) - (oldHt.repBonus || 0);
            if (repDiff > 0) {
                player.townReputation = player.townReputation || {};
                player.townReputation[house.townId] = Math.min(100, (player.townReputation[house.townId] || 0) + repDiff);
            }
        }

        Engine.logEvent('🏗️ ' + player.fullName + ' upgraded to ' + newHt.name + ' (' + upgradeCost + 'g after ' + credit + 'g credit).');
        grantXP(8, 'upgrade house');
        return { success: true, message: '🏗️ Upgraded to ' + newHt.name + ' for ' + upgradeCost + 'g (saved ' + credit + 'g from old house)!' };
    }

    function setPrimaryHouse(houseId) {
        var house = (player.houses || []).find(h => h.id === houseId);
        if (!house) return { success: false, message: 'House not found.' };
        if (house.isRental) return { success: false, message: 'Cannot set a rental property as primary home.' };
        player.primaryHouseId = houseId;
        return { success: true, message: 'Primary home updated.' };
    }

    function getHouseInTown(townId) {
        if (!player.houses) return null;
        return player.houses.find(h => h.townId === townId && !h.isRental) || null;
    }

    // Old rest functions removed — replaced by restForTicks() in §12J Energy System

    function rentOutHouse(houseId, monthlyRent) {
        var house = (player.houses || []).find(h => h.id === houseId);
        if (!house) return { success: false, message: 'House not found.' };
        if (house.id === player.primaryHouseId) return { success: false, message: 'Cannot rent out your primary home.' };

        // Toggling off rental
        if (house.isRental && monthlyRent === undefined) {
            // If tenant exists, start eviction (30 days from last payment)
            if (house.tenantId) {
                house.evictionDay = (house.lastRentDay || Engine.getDay()) + 30;
                return { success: true, message: 'Eviction notice sent. Tenant will leave by day ' + house.evictionDay + '.' };
            }
            house.isRental = false;
            house.monthlyRent = 0;
            return { success: true, message: 'House no longer listed for rent.' };
        }

        // Setting or updating rent
        var day = Engine.getDay();
        if (house.isRental && house.rentSetDay === day) {
            return { success: false, message: 'You can only change the rent price once per day.' };
        }

        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        var rent = monthlyRent;
        if (rent === undefined || rent === null) {
            // Calculate recommended rent
            rent = getRecommendedRent(house);
        }
        rent = Math.max(0, Math.floor(rent));

        house.isRental = true;
        house.monthlyRent = rent;
        house.rentSetDay = day;
        if (!house.tenantId) house.tenantId = null;
        if (!house.tenantType) house.tenantType = null;
        if (!house.lastRentDay) house.lastRentDay = 0;
        if (!house.evictionDay) house.evictionDay = null;
        house.rentAccumulated = house.rentAccumulated || 0;

        return { success: true, message: 'House listed for rent at ' + rent + 'g/month. 💰' };
    }

    // Calculate recommended rent (5-30% below max NPC/EM willingness)
    function getRecommendedRent(house) {
        var maxRent = getMaxRentWillingness(house);
        var discountPct = 0.05 + (Engine.getRng ? Engine.getRng().randFloat(0, 0.25) : Math.random() * 0.25);
        return Math.max(1, Math.floor(maxRent * (1 - discountPct)));
    }

    // Calculate the max rent any NPC/EM in this location would pay
    function getMaxRentWillingness(house) {
        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        if (!ht) return 1;
        var town = Engine.findTown(house.townId);
        var prosperity = town ? (town.prosperity || 50) : 50;
        var catMultiplier = { village: 0.5, town: 1.0, city: 1.5, capital_city: 2.0 };
        var cat = town ? (town.category || 'town') : 'town';
        var mult = catMultiplier[cat] || 1.0;
        // Base rent: comfort × prosperity / 50 × town category multiplier
        var baseRent = Math.floor(ht.comfort * (prosperity / 50) * mult);
        // Security and storage bonuses
        baseRent += Math.floor(ht.storage * 0.05);
        baseRent += Math.floor(ht.security * 10);
        return Math.max(1, baseRent);
    }

    function collectRent() {
        var totalRent = 0;
        if (!player.houses) return 0;
        var day = Engine.getDay();
        for (var i = 0; i < player.houses.length; i++) {
            var house = player.houses[i];
            if (!house.isRental) continue;

            // Process evictions
            if (house.evictionDay && day >= house.evictionDay) {
                var evictedName = '';
                if (house.tenantId) {
                    var evicted = Engine.findPerson(house.tenantId);
                    evictedName = evicted ? ((evicted.firstName || '') + ' ' + (evicted.lastName || '')) : 'tenant';
                    // Clear tenant housing reference
                    if (evicted) evicted.rentedHouseId = null;
                }
                house.tenantId = null;
                house.tenantType = null;
                house.evictionDay = null;
                if (evictedName) Engine.logEvent('🏠 ' + evictedName + ' has been evicted from your rental property.');
                continue;
            }

            // No tenant = no income (but property is listed)
            if (!house.tenantId) continue;

            // Monthly rent collection (every 30 days)
            if (house.lastRentDay && (day - house.lastRentDay) < 30) continue;

            var rent = house.monthlyRent || 0;
            if (rent <= 0) continue;

            // Check if tenant can pay
            var tenant = Engine.findPerson(house.tenantId);
            if (!tenant || !tenant.alive) {
                // Tenant died or disappeared
                house.tenantId = null;
                house.tenantType = null;
                Engine.logEvent('🏠 A rental tenant has passed away or left.');
                continue;
            }

            if ((tenant.gold || 0) >= rent) {
                tenant.gold -= rent;
                player.gold += rent;
                logFinance(rent, 'rent_income', 'Rent from ' + ((Engine.findTown(house.townId) || {}).name || 'property'));
                player.stats.totalGoldEarned += rent;
                house.rentAccumulated = (house.rentAccumulated || 0) + rent;
                house.lastRentDay = day;
                totalRent += rent;
            } else {
                // Tenant can't afford — queue negotiation request
                if (!player.rentNegotiations) player.rentNegotiations = [];
                var existingNeg = player.rentNegotiations.find(function(n) { return n.houseId === house.id; });
                if (!existingNeg) {
                    var tenantName = (tenant.firstName || '') + ' ' + (tenant.lastName || '');
                    var desiredRent = Math.floor(rent * 0.7); // tenant asks for 30% less
                    player.rentNegotiations.push({
                        houseId: house.id,
                        tenantId: house.tenantId,
                        tenantName: tenantName,
                        currentRent: rent,
                        requestedRent: desiredRent,
                        day: day
                    });
                    Engine.logEvent('💬 ' + tenantName + ' cannot afford rent (' + rent + 'g) and is requesting a reduction to ' + desiredRent + 'g.');
                }
            }
        }
        return totalRent;
    }

    // Handle rent negotiation response from player
    function respondToRentNegotiation(houseId, decision, counterOffer) {
        if (!player.rentNegotiations) return { success: false, message: 'No pending negotiations.' };
        var negIdx = player.rentNegotiations.findIndex(function(n) { return n.houseId === houseId; });
        if (negIdx === -1) return { success: false, message: 'Negotiation not found.' };
        var neg = player.rentNegotiations[negIdx];
        var house = (player.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) { player.rentNegotiations.splice(negIdx, 1); return { success: false, message: 'House not found.' }; }
        var tenant = Engine.findPerson(neg.tenantId);

        player.rentNegotiations.splice(negIdx, 1);

        if (decision === 'accept') {
            house.monthlyRent = neg.requestedRent;
            house.rentSetDay = Engine.getDay();
            Engine.logEvent('🤝 You agreed to lower rent for ' + neg.tenantName + ' to ' + neg.requestedRent + 'g/month.');
            return { success: true, message: 'Rent lowered to ' + neg.requestedRent + 'g/month.' };
        } else if (decision === 'counter' && counterOffer !== undefined) {
            var offer = Math.max(0, Math.floor(counterOffer));
            // Tenant evaluates counter offer
            if (tenant && (tenant.gold || 0) >= offer * 0.8) {
                house.monthlyRent = offer;
                house.rentSetDay = Engine.getDay();
                Engine.logEvent('🤝 ' + neg.tenantName + ' accepted your counter-offer of ' + offer + 'g/month.');
                return { success: true, message: neg.tenantName + ' accepted ' + offer + 'g/month.' };
            } else {
                // Tenant decides to leave
                house.evictionDay = (house.lastRentDay || Engine.getDay()) + 30;
                Engine.logEvent('😤 ' + neg.tenantName + ' rejected your counter-offer and will leave by day ' + house.evictionDay + '.');
                return { success: true, message: neg.tenantName + ' rejected the offer and will leave.' };
            }
        } else {
            // Reject — tenant may leave depending on alternatives
            if (tenant) {
                var maxRent = getMaxRentWillingness(house);
                if (house.monthlyRent > maxRent * 1.2) {
                    // Rent is too high, tenant leaves
                    house.evictionDay = (house.lastRentDay || Engine.getDay()) + 30;
                    Engine.logEvent('😤 ' + neg.tenantName + ' decided to leave after rent negotiation failed.');
                    return { success: true, message: neg.tenantName + ' will leave the property.' };
                }
                // Tenant stays grudgingly but might leave next month
                Engine.logEvent('😐 ' + neg.tenantName + ' stays for now but is unhappy about the rent.');
                return { success: true, message: neg.tenantName + ' stays for now.' };
            }
            return { success: true, message: 'Negotiation rejected.' };
        }
    }

    // Evict a tenant from a rental property
    function evictTenant(houseId) {
        var house = (player.houses || []).find(function(h) { return h.id === houseId; });
        if (!house) return { success: false, message: 'House not found.' };
        if (!house.tenantId) return { success: false, message: 'No tenant to evict.' };
        var tenant = Engine.findPerson(house.tenantId);
        var tenantName = tenant ? ((tenant.firstName || '') + ' ' + (tenant.lastName || '')) : 'tenant';
        house.evictionDay = (house.lastRentDay || Engine.getDay()) + 30;
        Engine.logEvent('🏠 Eviction notice issued to ' + tenantName + '. They will leave by day ' + house.evictionDay + '.');
        return { success: true, message: 'Eviction notice sent. ' + tenantName + ' will leave by day ' + house.evictionDay + '.' };
    }

    // ========================================================
    // §12H1b  PROPERTY LISTING FOR SALE
    // ========================================================

    function listBuildingForSale(buildingId, price) {
        var bld = (player.buildings || []).find(function(b) { return b.id === buildingId; });
        if (!bld) return { success: false, message: 'Building not found.' };

        // Toggle off
        if (bld.forSale && price === undefined) {
            bld.forSale = false;
            bld.salePrice = 0;
            return { success: true, message: 'Building removed from sale.' };
        }

        // Daily price change limit
        var day = Engine.getDay();
        if (bld.forSale && bld.salePriceSetDay === day) {
            return { success: false, message: 'You can only change the sale price once per day.' };
        }

        // Calculate recommended price (deterministic: 85% of max buyer price)
        var maxPrice = Engine.getPropertyMaxBuyPrice(bld, bld.townId);
        var recommendedPrice = Math.max(1, Math.floor(maxPrice * 0.85));

        if (price === undefined || price === null) {
            price = recommendedPrice;
        }
        price = Math.max(0, Math.floor(price));

        bld.forSale = true;
        bld.salePrice = price;
        bld.salePriceSetDay = day;

        // Also mark the town building as for sale
        var town = Engine.findTown(bld.townId);
        if (town) {
            var townBld = (town.buildings || []).find(function(tb) { return tb.ownerId === 'player' && tb.type === bld.type; });
            if (townBld) {
                townBld.forSale = true;
                townBld.salePrice = price;
            }
        }

        var bt = Engine.findBuildingType(bld.type);
        var bName = bt ? bt.name : bld.type;
        Engine.logEvent('📋 ' + player.fullName + ' listed ' + bName + ' for sale at ' + price + 'g.');
        return { success: true, message: '📋 ' + bName + ' listed for ' + price + 'g. Recommended: ' + recommendedPrice + 'g. Max buyer will pay: ' + (hasSkill('property_appraiser') ? maxPrice + 'g' : '???') + '.', recommendedPrice: recommendedPrice, maxPrice: hasSkill('property_appraiser') ? maxPrice : null };
    }

    function listLandForSale(townId, price) {
        if (!player.landOwned || !player.landOwned[townId] || player.landOwned[townId] <= 0) {
            return { success: false, message: 'No land owned in this town.' };
        }
        // Check no buildings/houses using all land
        var usedSlots = getUsedLandSlots(townId);
        if (usedSlots >= player.landOwned[townId]) {
            return { success: false, message: 'All land is in use. Demolish a building or sell a house first.' };
        }

        if (!player.landForSale) player.landForSale = [];
        // Check daily limit
        var day = Engine.getDay();
        var existing = player.landForSale.find(function(l) { return l.townId === townId; });
        if (existing && existing.priceSetDay === day) {
            return { success: false, message: 'You can only change the land price once per day.' };
        }

        var maxPrice = Engine.getPropertyMaxBuyPrice({ type: 'land' }, townId);
        var recommendedPrice = Math.max(1, Math.floor(maxPrice * 0.85));

        if (price === undefined || price === null) price = recommendedPrice;
        price = Math.max(0, Math.floor(price));

        if (existing) {
            existing.price = price;
            existing.priceSetDay = day;
        } else {
            player.landForSale.push({ townId: townId, price: price, priceSetDay: day });
        }

        var town = Engine.findTown(townId);
        Engine.logEvent('📋 ' + player.fullName + ' listed land in ' + (town ? town.name : 'unknown') + ' for ' + price + 'g.');
        return { success: true, message: '📋 Land listed for ' + price + 'g. Recommended: ' + recommendedPrice + 'g. Max buyer will pay: ' + (hasSkill('property_appraiser') ? maxPrice + 'g' : '???') + '.', recommendedPrice: recommendedPrice, maxPrice: hasSkill('property_appraiser') ? maxPrice : null };
    }

    function cancelLandListing(townId) {
        if (!player.landForSale) return { success: false, message: 'No listings.' };
        var idx = player.landForSale.findIndex(function(l) { return l.townId === townId; });
        if (idx === -1) return { success: false, message: 'No land listed in this town.' };
        player.landForSale.splice(idx, 1);
        return { success: true, message: 'Land listing removed.' };
    }

    // ========================================================
    // §12H2  HOUSING FEATURES TICK (stables, garden, workshop)
    // ========================================================
    function tickHousing() {
        if (!player.houses || player.houses.length === 0) return;
        var day = Engine.getDay();

        for (var i = 0; i < player.houses.length; i++) {
            var house = player.houses[i];
            if (house.isRental) continue;
            var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
            if (!ht) continue;

            // ── hasStables: horse stamina recovery when player is in this town ──
            if (ht.hasStables && player.townId === house.townId && !player.traveling) {
                for (var hi = 0; hi < player.horses.length; hi++) {
                    var horse = player.horses[hi];
                    if (horse.stamina < 100) {
                        horse.stamina = Math.min(100, horse.stamina + 2); // recover 2 stamina/day
                    }
                }
            }

            // ── canGrow: passive crop/herb growing (every 7 days) ──
            if (ht.canGrow && ht.canGrow.length > 0) {
                if (!house._lastGrowDay) house._lastGrowDay = day;
                if (day - house._lastGrowDay >= 7) {
                    house._lastGrowDay = day;
                    for (var gi = 0; gi < ht.canGrow.length; gi++) {
                        var crop = ht.canGrow[gi];
                        var growQty = 1;
                        // Herbalist skill doubles herb yield
                        if (crop === 'herbs' && hasSkill('herbalist')) growQty = 2;
                        // hasGarden doubles all garden output
                        if (ht.hasGarden) growQty *= 2;

                        // Store in house storage if available, else player inventory
                        if (!house.homeStorage) house.homeStorage = {};
                        var storageUsed = Object.values(house.homeStorage).reduce(function(s, v) { return s + v; }, 0);
                        if (storageUsed + growQty <= (ht.storage || 40)) {
                            house.homeStorage[crop] = (house.homeStorage[crop] || 0) + growQty;
                        } else {
                            player.inventory[crop] = (player.inventory[crop] || 0) + growQty;
                        }
                    }
                    if (day % 28 === 0) {
                        Engine.logEvent('🌱 Your garden produced crops this month.');
                    }
                }
            }
        }
    }

    // ========================================================
    // §12H3  HOME WORKSHOP CRAFTING
    // ========================================================
    var HOME_CRAFT_RECIPES = [
        { id: 'bandages', name: 'Bandages', inputs: { cloth: 2 }, output: 'bandages', qty: 3, ticks: 3 },
        { id: 'herbal_remedy', name: 'Herbal Remedy', inputs: { herbs: 3 }, output: 'herbal_remedy', qty: 1, ticks: 5, skill: 'herbalist' },
        { id: 'herbal_poultice', name: 'Herbal Poultice', inputs: { herbs: 2, cloth: 1 }, output: 'herbal_poultice', qty: 1, ticks: 4, skill: 'first_aid' },
        { id: 'rope', name: 'Rope', inputs: { hemp: 3 }, output: 'rope', qty: 2, ticks: 4 },
        { id: 'candles', name: 'Candles', inputs: { hide: 1 }, output: 'candles', qty: 3, ticks: 2 },
        { id: 'preserved_food', name: 'Preserved Food', inputs: { meat: 2, salt: 1 }, output: 'preserved_food', qty: 2, ticks: 5 },
    ];

    function getHomeCraftRecipes() {
        // Only available if player has a workshop house in current town
        var house = getHouseInTown(player.townId);
        if (!house) return [];
        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        if (!ht || !ht.hasWorkshop) return [];

        return HOME_CRAFT_RECIPES.filter(function(r) {
            if (r.skill && !hasSkill(r.skill)) return false;
            return true;
        });
    }

    function craftAtHome(recipeId) {
        if (player.traveling) return { success: false, message: 'Cannot craft while traveling.' };

        // Energy check
        var eCraft = checkEnergyForAction(ENERGY_CONFIG.CRAFT_COST || 2);
        if (eCraft.blocked) return { success: false, message: eCraft.message };

        var house = getHouseInTown(player.townId);
        if (!house) return { success: false, message: 'No house in this town.' };
        var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
        if (!ht || !ht.hasWorkshop) return { success: false, message: 'Your home needs a workshop to craft items.' };

        var recipe = HOME_CRAFT_RECIPES.find(function(r) { return r.id === recipeId; });
        if (!recipe) return { success: false, message: 'Unknown recipe.' };
        if (recipe.skill && !hasSkill(recipe.skill)) return { success: false, message: 'You need the ' + recipe.skill + ' skill for this recipe.' };

        // Check inputs — from inventory + house storage
        for (var resId in recipe.inputs) {
            var needed = recipe.inputs[resId];
            var have = (player.inventory[resId] || 0) + ((house.homeStorage && house.homeStorage[resId]) || 0);
            if (have < needed) return { success: false, message: 'Need ' + needed + ' ' + resId + ' (have ' + have + ').' };
        }

        if (typeof Game !== 'undefined' && Game.advanceTicks) Game.advanceTicks(recipe.ticks || 3);

        // Consume inputs (inventory first, then house storage)
        for (var resId in recipe.inputs) {
            var toConsume = recipe.inputs[resId];
            var fromInv = Math.min(toConsume, player.inventory[resId] || 0);
            player.inventory[resId] = (player.inventory[resId] || 0) - fromInv;
            toConsume -= fromInv;
            if (toConsume > 0 && house.homeStorage) {
                house.homeStorage[resId] = (house.homeStorage[resId] || 0) - toConsume;
            }
        }

        // Produce output
        player.inventory[recipe.output] = (player.inventory[recipe.output] || 0) + recipe.qty;
        grantXP(2, 'crafting');
        consumeEnergy(ENERGY_CONFIG.CRAFT_COST || 2);

        Engine.logEvent('🔨 Crafted ' + recipe.qty + 'x ' + recipe.name + ' at home workshop.');
        return { success: true, message: 'Crafted ' + recipe.qty + 'x ' + recipe.name + '!' };
    }

    // ========================================================
    // §12I  LAND OWNERSHIP
    // ========================================================

    // Count total land slots used by player in a town (houses + buildings, respecting landSlots)
    function getUsedLandSlots(townId) {
        var used = 0;
        (player.houses || []).forEach(function(h) {
            if (h.townId !== townId) return;
            var hht = CONFIG.HOUSING_TYPES.find(function(x) { return x.id === h.type; });
            if (hht && (hht.id === 'apartment' || hht.portable || hht.fromApartmentBuilding)) return;
            used += (hht && hht.landSlots) ? hht.landSlots : 1;
        });
        (player.buildings || []).forEach(function(b) {
            if (b.townId !== townId) return;
            var bbt = Engine.findBuildingType(b.type);
            used += (bbt && bbt.landSlots) ? bbt.landSlots : 1;
        });
        return used;
    }
    function getLandCost(townId) {
        var town = Engine.findTown(townId);
        if (!town) return CONFIG.LAND_COST_BASE;
        var cat = town.category || 'town';
        var sizeMultiplier = (CONFIG.LAND_COST_MULTIPLIER && CONFIG.LAND_COST_MULTIPLIER[cat]) || (CONFIG.HOUSING_LABOR_MULTIPLIER && CONFIG.HOUSING_LABOR_MULTIPLIER[cat]) || 1.0;
        var prosperityMultiplier = Math.max(0.5, (town.prosperity || 50) / 50);
        return Math.floor(CONFIG.LAND_COST_BASE * sizeMultiplier * prosperityMultiplier);
    }

    function getActiveSubsidy(townId) {
        var town = Engine.findTown(townId);
        if (!town || !town.kingdomId) return null;
        var world = Engine.getWorld();
        if (!world) return null;
        var kingdom = Engine.findKingdom(town.kingdomId);
        if (!kingdom || !kingdom.landSubsidies) return null;
        for (var si = 0; si < kingdom.landSubsidies.length; si++) {
            var sub = kingdom.landSubsidies[si];
            if (sub.townId === townId && sub.expiresDay > world.day) return sub;
        }
        return null;
    }

    function getSubsidizedLandCost(townId) {
        var base = getLandCost(townId);
        var sub = getActiveSubsidy(townId);
        if (!sub) return base;
        return Math.floor(base * (1 - sub.discount));
    }

    function buyLand(townId, useSubsidy) {
        if (isJailed()) return { success: false, message: 'You are in jail.' };
        var town = Engine.findTown(townId);
        if (!town) return { success: false, message: 'Town not found.' };

        // Immigration policy enforcement — closed borders block foreign land purchase
        if (town.kingdomId && player.citizenshipKingdomId !== town.kingdomId) {
            var kingdom = Engine.findKingdom(town.kingdomId);
            if (kingdom && hasSpecialLaw(kingdom, 'immigration_policy') && kingdom.immigrationPolicy === 'closed') {
                return { success: false, message: '🚫 ' + kingdom.name + ' has closed borders. Non-citizens cannot buy land. Earn citizenship first.' };
            }
        }

        var cat = town.category || 'village';
        var maxPlots = CONFIG.LAND_PLOTS_BASE[cat] || 5;
        // Check rank-based land limit
        var rankIdx = getPlayerRankIndex();
        var rank = CONFIG.SOCIAL_RANKS[rankIdx];
        var ownedTotal = 0;
        for (var tid in player.landOwned) ownedTotal += (player.landOwned[tid] || 0);
        if (rank && rank.maxLand !== undefined && ownedTotal >= rank.maxLand) {
            return { success: false, message: 'Your rank (' + rank.name + ') limits you to ' + rank.maxLand + ' total land plots. You own ' + ownedTotal + '. Advance your rank to buy more.' };
        }
        var cost;
        var lockedType = null;
        if (useSubsidy) {
            var sub = getActiveSubsidy(townId);
            if (!sub) return { success: false, message: 'No active land subsidy in this town.' };
            cost = getSubsidizedLandCost(townId);
            lockedType = sub.buildingType;
        } else {
            cost = getLandCost(townId);
        }
        if (player.gold < cost) return { success: false, message: 'Need ' + cost + 'g to buy land.' };
        player.gold -= cost;
        logFinance(-cost, 'land', 'Bought land' + (lockedType ? ' (subsidized: ' + lockedType + ')' : ''));
        player.stats.totalGoldSpent += cost;
        player.landOwned = player.landOwned || {};
        player.landOwned[townId] = (player.landOwned[townId] || 0) + 1;
        if (lockedType) {
            player.subsidizedLand = player.subsidizedLand || {};
            player.subsidizedLand[townId] = player.subsidizedLand[townId] || [];
            player.subsidizedLand[townId].push({ buildingType: lockedType });
        }
        if (typeof Game !== 'undefined' && Game.advanceTicks) Game.advanceTicks(3);
        var btName = lockedType ? (Engine.findBuildingType(lockedType) || {}).name || lockedType : null;
        var msg = lockedType
            ? 'Bought subsidized land in ' + town.name + ' for ' + cost + 'g (must build: ' + btName + '). 🏗️'
            : 'Bought land in ' + town.name + ' for ' + cost + 'g. 🏗️';
        Engine.logEvent(player.fullName + ' purchased a land plot in ' + town.name + ' for ' + cost + 'g.' + (lockedType ? ' (Subsidized — ' + btName + ' only)' : ''));
        return { success: true, message: msg };
    }

    function sellLand(townId) {
        if (!player.landOwned || !player.landOwned[townId] || player.landOwned[townId] <= 0) {
            return { success: false, message: 'You own no land here.' };
        }
        // Check that there's free land to sell (using proper slot counting)
        var usedSlots = getUsedLandSlots(townId);
        if (usedSlots >= player.landOwned[townId]) {
            return { success: false, message: 'All land plots are occupied. Sell buildings/houses first.' };
        }
        // Sell subsidized (locked) plots first — they have lower value
        var isSubsidized = false;
        if (player.subsidizedLand && player.subsidizedLand[townId] && player.subsidizedLand[townId].length > 0) {
            // Only sell a subsidized plot if it's unoccupied (free slots > subsidized count isn't needed — just pop one)
            isSubsidized = true;
            player.subsidizedLand[townId].pop();
            if (player.subsidizedLand[townId].length <= 0) delete player.subsidizedLand[townId];
        }
        var basePrice = isSubsidized ? getSubsidizedLandCost(townId) : getLandCost(townId);
        var sellPrice = Math.floor(basePrice * CONFIG.LAND_SELL_RATIO);
        player.gold += sellPrice;
        logFinance(sellPrice, 'land', 'Sold land' + (isSubsidized ? ' (subsidized)' : ''));
        player.stats.totalGoldEarned += sellPrice;
        player.landOwned[townId]--;
        if (player.landOwned[townId] <= 0) delete player.landOwned[townId];
        return { success: true, message: 'Sold land for ' + sellPrice + 'g.' + (isSubsidized ? ' (Subsidized plot)' : '') + ' 💰' };
    }

    function getOwnedLand(townId) {
        return (player.landOwned && player.landOwned[townId]) || 0;
    }

    // ========================================================
    // §12J  ENERGY & THIRST SYSTEM (replaces old Fatigue)
    // ========================================================

    function getMaxEnergy() {
        var max = ENERGY_CONFIG.BASE_MAX;
        for (var i = 0; i < ENERGY_CONFIG.ENDURANCE_TIERS.length; i++) {
            if (hasSkill(ENERGY_CONFIG.ENDURANCE_TIERS[i].id)) {
                max = ENERGY_CONFIG.ENDURANCE_TIERS[i].maxEnergy;
            }
        }
        player.maxEnergy = max;
        return max;
    }

    function consumeEnergy(amount) {
        player.energy = Math.max(0, (player.energy || ENERGY_CONFIG.START) - amount);
        // Sync legacy fatigue for backward compat
        player.fatigue = Math.max(0, getMaxEnergy() - player.energy);
        // Mark that energy was consumed this tick (prevents double-drain with passive decay)
        player._energyConsumedThisTick = true;
    }

    function restoreEnergy(amount) {
        var max = getMaxEnergy();
        player.energy = Math.min(max, (player.energy || 0) + amount);
        player.fatigue = Math.max(0, max - player.energy);
    }

    function getJobEnergyCostPerTick(job) {
        // If explicitly set on job definition, use it
        if (job.energyCost != null) return job.energyCost;

        var name = (job.name || '').toLowerCase();

        // Very heavy (4.0) — extreme physical
        if (name.includes('arena') || name.includes('tournament')) return 4.0;

        // Heavy (3.0) — hard labor / dangerous fieldwork
        if (name.includes('mine') || name.includes('dock') || name.includes('lumber') ||
            name.includes('well dig') || name.includes('rescue') || name.includes('deep sea') ||
            name.includes('siege') || name.includes('road repair') || name.includes('caravan loader') ||
            name.includes('gravedigger') || name.includes('rebuilder') || name.includes('chop wood') ||
            name.includes('load cargo') || name.includes('carry supplies')) return 3.0;

        // Medium-heavy (2.5) — moderate physical + skill
        if (name.includes('soldier') || name.includes('smithy') || name.includes('harvest') ||
            name.includes('ship repair') || name.includes('fence mend') || name.includes('blacksmith') ||
            name.includes('castle work') || name.includes('caravan guard')) return 2.5;

        // Medium (2.0) — standing/walking work
        if (name.includes('guard') || name.includes('stablehand') || name.includes('farm') ||
            name.includes('watchman') || name.includes('plague nurse') || name.includes('war medic') ||
            name.includes('navigator') || name.includes('quarantine') || name.includes('guild enforcer') ||
            name.includes('privateer') || name.includes('weapons courier')) return 2.0;

        // Light-medium (1.5) — moderate activity
        if (name.includes('castle servant') || name.includes('messenger') || name.includes('shepherd') ||
            name.includes('market crier') || name.includes('lamplighter') || name.includes('herb') ||
            name.includes('itinerant') || name.includes('customs') || name.includes('bakery') ||
            name.includes('tailor') || name.includes('assist') || name.includes('warehouse') ||
            name.includes('sweep') || name.includes('deliver') || name.includes('tend')) return 1.5;

        // Light (1.0) — mental or entertainment work
        if (name.includes('entertainer') || name.includes('tax collector') || name.includes('spy') ||
            name.includes('merchant') || name.includes('count inventory') || name.includes('traveling')) return 1.0;

        // Very light (0.5) — desk work
        if (name.includes('scribe') || name.includes('clerk') || name.includes('diplomat') ||
            name.includes('banker')) return 0.5;

        // Default: light-medium
        return 1.5;
    }

    function checkEnergyForAction(energyCost) {
        var cost = energyCost || 0;
        var energy = (player.energy != null) ? player.energy : ENERGY_CONFIG.START;
        if (energy <= ENERGY_CONFIG.COLLAPSE_THRESHOLD) {
            var rng = Engine.getRng();
            if (rng && rng.chance(ENERGY_CONFIG.COLLAPSE_CHANCE)) {
                if (typeof Game !== 'undefined' && Game.advanceTicks) Game.advanceTicks(30);
                restoreEnergy(30);
                var injuryChance = rng.chance(0.30);
                if (injuryChance) {
                    player.injuries = player.injuries || [];
                    player.injuries.push({ type: 'exhaustion_collapse', severity: 'mild', dayOccurred: Engine.getDay(), treated: false });
                }
                Engine.logEvent(player.fullName + ' collapsed from exhaustion!');
                return { blocked: true, message: '💫 You collapsed from exhaustion!' + (injuryChance ? ' You injured yourself in the fall.' : '') };
            }
        }
        if (energy < ENERGY_CONFIG.ACTION_BLOCK) {
            return { blocked: true, message: '😵 Too exhausted! You need to rest. (Energy: ' + Math.floor(energy) + ')' };
        }
        if (cost > 0 && energy < cost) {
            return { blocked: true, message: '😴 Not enough energy for this action. Need ' + Math.ceil(cost) + ', have ' + Math.floor(energy) + '. Rest first!' };
        }
        return { blocked: false };
    }

    function getEnergyDebuffs() {
        var max = getMaxEnergy();
        var threshold = max * ENERGY_CONFIG.LOW_DEBUFF_THRESHOLD;
        var energy = (player.energy != null) ? player.energy : ENERGY_CONFIG.START;
        if (energy > threshold) return null;
        return ENERGY_CONFIG.DEBUFFS;
    }

    function getLowEnergyModifier(stat) {
        var debuffs = getEnergyDebuffs();
        if (!debuffs) return 0;
        return debuffs[stat] || 0;
    }

    // Legacy wrapper — keeps old addFatigue calls working
    function addFatigue(ticks) {
        consumeEnergy(ticks * CONFIG.FATIGUE_PER_TICK_COST);
    }

    // Legacy wrapper
    function checkFatigueForAction() {
        return checkEnergyForAction(0);
    }

    // Passive energy drain per subtick (0.25 × 60 = 15/day)
    // Applies always when not resting — sitting in town, traveling, etc.
    function energySubtick() {
        if (!player.resting) {
            player.energy = Math.max(0, (player.energy || ENERGY_CONFIG.START) - 0.25);
            player.fatigue = Math.max(0, getMaxEnergy() - player.energy);
        }
    }

    function tickEnergy() {
        // Passive energy drain is now handled in energySubtick() (60x/day)
        // This daily tick only handles: auto-rest and passive recovery
        player._energyConsumedThisTick = false;

        // Auto-rest: if enabled and energy below 10, start resting automatically
        if (player.autoRest !== false && !player.resting && (player.energy || 0) < 10) {
            var opts = getAvailableRestOptions();
            if (opts.length > 0) {
                // Pick best option player can afford (highest energyPerTick)
                var best = null;
                for (var ri = 0; ri < opts.length; ri++) {
                    var opt = opts[ri];
                    if (opt.cost > 0 && player.gold < opt.cost) continue;
                    if (!best || opt.energyPerTick > best.energyPerTick) best = opt;
                }
                if (best) {
                    var result = restForTicks(best.id, 8);
                    if (result && result.success) {
                        Engine.logEvent('💤 Auto-rest: ' + best.name + (best.cost > 0 ? ' (' + best.cost + 'g)' : ''));
                    }
                }
            }
        }

        // Natural daily passive recovery (only when housed/idle — NOT while traveling)
        if (!player.traveling) {
            var house = getHouseInTown(player.townId);
            var recovery = house ? ENERGY_CONFIG.PASSIVE_RECOVERY_HOUSED : ENERGY_CONFIG.PASSIVE_RECOVERY_HOMELESS;
            // Reduce recovery when hungry or thirsty
            if ((player.hunger || 0) <= 0) recovery *= 0.25;  // Starving: 75% less recovery
            else if ((player.hunger || 0) <= 20) recovery *= 0.5;  // Very hungry: 50% less
            if ((player.thirst || 0) <= 0) recovery *= 0.25;  // Dehydrated: 75% less
            else if ((player.thirst || 0) <= 20) recovery *= 0.5;  // Very thirsty: 50% less
            restoreEnergy(recovery);
        }
    }

    // Keep old name as alias
    function tickFatigue() {
        tickEnergy();
    }

    function getLodgingCost(type) {
        var town = Engine.findTown(player.townId);
        var prosperity = (town && town.prosperity) || 50;
        var catMult = { village: 0.5, town: 1.0, city: 1.8, capital_city: 3.0 };
        var cat = (town && town.category) || 'town';
        var cm = catMult[cat] || 1.0;
        // prosperity 0-100 maps to 0.5-1.5 multiplier
        var pm = 0.5 + (prosperity / 100);
        if (type === 'inn_room') {
            // Base 3g, range 3-15g
            return Math.max(3, Math.min(15, Math.round(3 * cm * pm)));
        } else if (type === 'tavern') {
            // Base 4g, range 4-20g
            return Math.max(4, Math.min(20, Math.round(4 * cm * pm)));
        }
        return 0;
    }

    function getRestEnergyRate(locationId) {
        var rate = ENERGY_CONFIG.REST_ENERGY_PER_TICK[locationId] || ENERGY_CONFIG.REST_ENERGY_PER_TICK.outside;
        // Wilderness Survival: +50% rest while traveling
        if (hasSkill('wilderness_survival') && (locationId === 'camping_kit_travel' || locationId === 'tent_travel' || locationId === 'bedroll_travel' || (player.traveling && locationId === 'outside'))) {
            rate *= 1.5;
        }
        return rate;
    }

    function getRestLocationId() {
        // Determine best rest location for player
        if (player.indentured && player.indentured.active) return 'master_quarters';
        if (player.militaryService && player.militaryService.active) return 'barracks';
        var house = getHouseInTown(player.townId);
        if (house) {
            var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
            if (ht) return house.type;
        }
        return null; // no home — must choose inn, tavern, or outside
    }

    function getAvailableRestOptions() {
        var options = [];

        // ── While traveling: only camping/roadside options ──
        if (player.traveling) {
            // Camping Kit (best travel rest)
            if ((player.inventory.camping_kit || 0) > 0) {
                options.push({
                    id: 'camping_kit_travel',
                    name: '🏕️ Camp with Kit',
                    cost: 0,
                    energyPerTick: getRestEnergyRate('camping_kit_travel'),
                    risks: [],
                    icon: '🏕️',
                });
            }
            // Tent
            if ((player.inventory.tent || 0) > 0) {
                options.push({
                    id: 'tent_travel',
                    name: '⛺ Rest in Tent',
                    cost: 0,
                    energyPerTick: getRestEnergyRate('tent_travel'),
                    risks: ['3% theft'],
                    icon: '⛺',
                });
            }
            // Bedroll
            if ((player.inventory.bedroll || 0) > 0) {
                options.push({
                    id: 'bedroll_travel',
                    name: '🛏️ Sleep on Bedroll',
                    cost: 0,
                    energyPerTick: getRestEnergyRate('bedroll_travel'),
                    risks: ['5% theft', '3% disease'],
                    icon: '🛏️',
                });
            }
            // Caravan Wagon (portable housing — rest in your wagon while traveling)
            var hasWagon = (player.houses || []).some(function(h) { return h.type === 'caravan_wagon'; });
            if (hasWagon) {
                options.push({
                    id: 'caravan_wagon',
                    name: '🛒 Rest in Caravan Wagon',
                    cost: 0,
                    energyPerTick: getRestEnergyRate('caravan_wagon'),
                    risks: ['2% theft'],
                    icon: '🛒',
                });
            }
            // Ship rest — if traveling by sea and ship has rest capability
            if (player.travelBySea) {
                var bestSailor = getBestShip();
                if (bestSailor && bestSailor.restBonus > 0) {
                    var shipRestRate = bestSailor.restBonus * 10; // Convert to energy/tick (0.7 → 7.0)
                    var stConfig = CONFIG.SHIP_TYPES[bestSailor.type];
                    options.push({
                        id: 'ship_cabin',
                        name: '⚓ Rest Aboard ' + bestSailor.name,
                        cost: 0,
                        energyPerTick: shipRestRate,
                        risks: [],
                        icon: '⚓',
                    });
                }
            }
            // Bare roadside (always available)
            options.push({
                id: 'outside',
                name: '🌙 Sleep on the Road',
                cost: 0,
                energyPerTick: getRestEnergyRate('outside'),
                risks: ['10% theft', '5% disease', '5% injury'],
                risk: 'Exposed on the road',
                icon: '🌙',
            });
            return options;
        }

        // ── In town: full rest options ──
        var house = getHouseInTown(player.townId);

        // Own home
        if (house) {
            var ht = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === house.type; });
            options.push({
                id: house.type,
                name: '🏠 ' + (ht ? ht.name : 'Home'),
                cost: 0,
                energyPerTick: getRestEnergyRate(house.type),
                risks: [],
            });
        }

        // Master's quarters
        if (player.indentured && player.indentured.active) {
            var master = Engine.findPerson(player.indentured.masterId);
            if (master && player.townId === master.townId) {
                options.push({
                    id: 'master_quarters',
                    name: '🛏️ Master\'s Quarters',
                    cost: 0,
                    energyPerTick: getRestEnergyRate('master_quarters'),
                    risks: [],
                });
            }
        }

        // Ship cabin — rest aboard docked ship at port
        var portTown = Engine.findTown(player.townId);
        if (portTown && portTown.isPort && player.ships && player.ships.length > 0) {
            var dockedShip = getBestShip();
            if (dockedShip && dockedShip.restBonus > 0) {
                var dockRestRate = dockedShip.restBonus * 10;
                options.push({
                    id: 'ship_cabin',
                    name: '⚓ Rest Aboard ' + dockedShip.name,
                    cost: 0,
                    energyPerTick: dockRestRate,
                    risks: [],
                    icon: '⚓',
                });
            }
        }

        // Military barracks
        if (player.militaryService && player.militaryService.active) {
            options.push({
                id: 'barracks',
                name: '⚔️ Military Barracks',
                cost: 0,
                energyPerTick: getRestEnergyRate('barracks'),
                risks: [],
            });
        }

        // Tavern (if town has one)
        if (player.townId) {
            var town = Engine.findTown(player.townId);
            if (town && town.buildings) {
                var hasTavern = town.buildings.some(function(b) { return b.type === 'tavern'; });
                if (hasTavern) {
                    options.push({
                        id: 'tavern',
                        name: '🍻 Tavern',
                        cost: getLodgingCost('tavern'),
                        energyPerTick: getRestEnergyRate('tavern'),
                        risks: [],
                        desc: 'Socialize while you rest — meet locals!',
                    });
                }
            }
        }

        // Inn (always available in towns)
        if (player.townId) {
            options.push({
                id: 'inn_room',
                name: '🏨 Inn Room',
                cost: getLodgingCost('inn_room'),
                energyPerTick: getRestEnergyRate('inn_room'),
                risks: [],
            });
        }

        // Sleep outside (always available)
        options.push({
            id: 'outside',
            name: '🌙 Sleep Outside',
            cost: 0,
            energyPerTick: getRestEnergyRate('outside'),
            risks: ['8% theft', '5% disease', '3% injury'],
        });

        return options;
    }

    function restForTicks(locationId, ticks) {
        var isTravelRest = locationId === 'camping_kit_travel' || locationId === 'tent_travel' || locationId === 'bedroll_travel';
        var isRoadsideRest = player.traveling && locationId === 'outside';

        // Block non-travel rest while traveling
        if (player.traveling && !isTravelRest && !isRoadsideRest) {
            return { success: false, message: 'Cannot rest here while traveling. Use camping gear or sleep roadside.' };
        }

        var rate = getRestEnergyRate(locationId);
        var max = getMaxEnergy();
        var energyNeeded = max - (player.energy || 0);
        var maxTicks = Math.ceil(energyNeeded / rate);
        var actualTicks = Math.min(ticks, maxTicks);
        if (actualTicks <= 0) return { success: false, message: 'Already at full energy.' };

        // Handle costs (only in-town lodging)
        if (locationId === 'inn_room') {
            var innCost = getLodgingCost('inn_room');
            if (player.gold < innCost) return { success: false, message: 'Need ' + innCost + 'g for an inn room.' };
            player.gold -= innCost;
            player.stats.totalGoldSpent = (player.stats.totalGoldSpent || 0) + innCost;
        } else if (locationId === 'tavern') {
            var tavCost = getLodgingCost('tavern');
            if (player.gold < tavCost) return { success: false, message: 'Need ' + tavCost + 'g for a tavern room.' };
            player.gold -= tavCost;
            player.stats.totalGoldSpent = (player.stats.totalGoldSpent || 0) + tavCost;
        }

        // Pause travel progress while resting (time passes but no distance covered)
        var wasTraveling = player.traveling;
        var savedTravelProgress = null;
        if (wasTraveling && player.travelData) {
            savedTravelProgress = {
                ticksRemaining: player.travelData.ticksRemaining,
                progress: player.travelData.progress
            };
        }

        // Advance time
        if (typeof Game !== 'undefined' && Game.advanceTicks) Game.advanceTicks(actualTicks);

        // Restore travel state so resting doesn't advance the journey
        if (wasTraveling && savedTravelProgress && player.travelData) {
            player.travelData.ticksRemaining = savedTravelProgress.ticksRemaining;
            player.travelData.progress = savedTravelProgress.progress;
        }

        // Restore energy
        var restored = actualTicks * rate;
        restoreEnergy(restored);

        // Injury recovery bonus for sheltered rest
        if (locationId !== 'outside' && !isRoadsideRest && locationId !== 'barracks') {
            if (player.injuries && player.injuries.length > 0) {
                for (var i = 0; i < player.injuries.length; i++) {
                    if (player.injuries[i].dayOccurred) player.injuries[i].dayOccurred -= 1;
                }
            }
        }

        var messages = ['Rested for ' + actualTicks + ' ticks. Energy: ' + Math.floor(player.energy) + '/' + max + '.'];
        player.lastRestDay = Engine.getDay();

        // Road/outdoor risks — roadside rest while traveling or sleeping outside in town
        if (isRoadsideRest || locationId === 'outside') {
            var rng = Engine.getRng();
            // Camping gear reduces risks
            var theftChance = isRoadsideRest ? 0.10 : 0.08;
            var goodsTheftChance = isRoadsideRest ? 0.06 : 0.04;
            var diseaseChance = isRoadsideRest ? 0.07 : 0.05;
            var injuryChance = isRoadsideRest ? 0.05 : 0.03;

            if (rng && rng.chance(theftChance)) {
                var stolen = Math.min(player.gold, Math.floor(Math.random() * 15) + 3);
                if (stolen > 0) {
                    player.gold -= stolen;
                    messages.push('💰 A thief stole ' + stolen + 'g while you slept!');
                }
            }
            if (rng && rng.chance(goodsTheftChance)) {
                var invKeys = Object.keys(player.inventory).filter(function(k) { return player.inventory[k] > 0; });
                if (invKeys.length > 0) {
                    var stolenGood = invKeys[Math.floor(Math.random() * invKeys.length)];
                    var stolenQty = Math.min(player.inventory[stolenGood], Math.floor(Math.random() * 3) + 1);
                    player.inventory[stolenGood] -= stolenQty;
                    if (player.inventory[stolenGood] <= 0) delete player.inventory[stolenGood];
                    messages.push('📦 Someone stole ' + stolenQty + ' ' + stolenGood + '!');
                }
            }
            if (rng && rng.chance(diseaseChance)) {
                player.illnesses = player.illnesses || [];
                player.illnesses.push({ type: 'cold', name: 'Common Cold', severity: 'mild', dayOccurred: Engine.getDay(), treated: false });
                messages.push('🤧 You caught a cold!');
            } else if (rng && rng.chance(0.02)) {
                player.illnesses = player.illnesses || [];
                player.illnesses.push({ type: 'fever', name: 'Fever', severity: 'moderate', dayOccurred: Engine.getDay(), treated: false });
                messages.push('🤒 You developed a fever!');
            }
            if (rng && rng.chance(injuryChance)) {
                player.injured = true;
                player.injuryDaysLeft = (player.injuryDaysLeft || 0) + 3;
                messages.push('🩹 You woke up with a minor injury!');
            }
        }

        // Travel camping gear has reduced risks (tent/bedroll/kit)
        if (isTravelRest) {
            var rng2 = Engine.getRng();
            var gearTheft = locationId === 'bedroll_travel' ? 0.05 : locationId === 'tent_travel' ? 0.03 : 0.01;
            var gearDisease = locationId === 'bedroll_travel' ? 0.03 : locationId === 'tent_travel' ? 0.01 : 0;

            if (rng2 && gearTheft > 0 && rng2.chance(gearTheft)) {
                var stolen2 = Math.min(player.gold, Math.floor(Math.random() * 10) + 2);
                if (stolen2 > 0) {
                    player.gold -= stolen2;
                    messages.push('💰 A thief stole ' + stolen2 + 'g while you camped!');
                }
            }
            if (rng2 && gearDisease > 0 && rng2.chance(gearDisease)) {
                player.illnesses = player.illnesses || [];
                player.illnesses.push({ type: 'cold', name: 'Common Cold', severity: 'mild', dayOccurred: Engine.getDay(), treated: false });
                messages.push('🤧 You caught a cold while camping.');
            }
        }

        // Tavern socializing — boost relationships with random locals
        if (locationId === 'tavern' && player.townId) {
            try {
                var rngTav = Engine.getRng();
                var townNpcs = Engine.getPeople(player.townId);
                if (townNpcs && townNpcs.length > 0) {
                    var alive = townNpcs.filter(function(n) { return n.alive !== false && n.age >= 14; });
                    if (alive.length > 0) {
                        var numToMeet = rngTav.randInt(2, Math.min(4, alive.length));
                        var shuffled = rngTav.shuffle(alive.slice());
                        var metNames = [];
                        for (var ti = 0; ti < numToMeet; ti++) {
                            var boost = rngTav.randInt(2, 5);
                            modifyRelationship(shuffled[ti].id, boost);
                            metNames.push((shuffled[ti].firstName || 'someone'));
                        }
                        messages.push('🍻 Socialized with ' + metNames.join(', ') + ' at the tavern!');
                    }
                }
            } catch (e) {}
        }

        var icon = isTravelRest ? '🏕️' : isRoadsideRest ? '🌙' : locationId === 'outside' ? '🌙' : locationId === 'inn_room' ? '🏨' : locationId === 'tavern' ? '🍻' : locationId === 'barracks' ? '⚔️' : '🏠';
        var restLabel = wasTraveling ? 'camped' : 'rested';
        Engine.logEvent(player.fullName + ' ' + restLabel + ' (' + actualTicks + ' ticks). Energy restored.');
        return { success: true, message: messages.join(' ') + ' ' + icon };
    }

    // Legacy rest functions — now redirect to restForTicks
    function restAtHome(townId) {
        var tid = townId || player.townId;
        if (player.traveling) return { success: false, message: 'Cannot rest while traveling.' };
        var house = getHouseInTown(tid);
        if (!house) return { success: false, message: 'You have no house in this town.' };
        var max = getMaxEnergy();
        var needed = max - (player.energy || 0);
        var rate = getRestEnergyRate(house.type);
        var ticks = Math.ceil(needed / rate);
        return restForTicks(house.type, ticks);
    }

    function restAtInn(townId) {
        return restForTicks('inn_room', Math.ceil((getMaxEnergy() - (player.energy || 0)) / getRestEnergyRate('inn_room')));
    }

    function sleepOutside() {
        return restForTicks('outside', Math.ceil((getMaxEnergy() - (player.energy || 0)) / getRestEnergyRate('outside')));
    }

    function restAtMasterQuarters() {
        if (!player.indentured || !player.indentured.active) {
            return { success: false, message: 'You are not an indentured servant.' };
        }
        return restForTicks('master_quarters', Math.ceil((getMaxEnergy() - (player.energy || 0)) / getRestEnergyRate('master_quarters')));
    }

    // ── Talk to Townsfolk ──

    function talkToTownsfolk() {
        if (player.traveling) return { success: false, message: 'Cannot talk while traveling.' };
        if (!player.townId) return { success: false, message: 'You must be in a town.' };

        var eCheck = checkEnergyForAction(1);
        if (eCheck.blocked) return { success: false, message: eCheck.message };

        var town = Engine.findTown(player.townId);
        if (!town) return { success: false, message: 'Town not found.' };
        var kingdom = Engine.findKingdom(town.kingdomId);
        var rng = Engine.getRng();
        if (!rng) return { success: false, message: 'Game not ready.' };

        // Advance time 1-2 ticks
        if (typeof Game !== 'undefined' && Game.advanceTicks) {
            Game.advanceTicks(rng.chance(0.5) ? 1 : 2);
        }

        // Pick a random NPC in town for the name
        var townPeople = Engine.getPeople ? Engine.getPeople() : [];
        var locals = [];
        for (var i = 0; i < townPeople.length; i++) {
            var p = townPeople[i];
            if (p.alive && p.townId === player.townId && p.age >= 16) {
                locals.push(p);
            }
        }
        // Use getPeopleCached if available (perf optimization)
        if (Engine.getPeopleCached) {
            locals = (Engine.getPeopleCached(player.townId) || []).filter(function(p) {
                return p.alive && p.age >= 16;
            });
        }

        var npc = locals.length > 0 ? locals[rng.randInt(0, locals.length - 1)] : null;
        var npcName = npc ? (npc.firstName + ' ' + npc.lastName) : 'A local';
        var npcOccupation = npc ? (npc.occupation || 'commoner') : 'commoner';
        var npcGender = npc ? (npc.sex === 'F' ? 'she' : 'he') : 'they';

        // Small rep gain from socializing
        if (kingdom) {
            player.reputation[kingdom.id] = Math.min(100, (player.reputation[kingdom.id] || 50) + 0.05);
        }

        // 25% useful info, 75% flavor
        var isUseful = rng.chance(0.25);

        if (isUseful) {
            return _generateUsefulInfo(town, kingdom, npc, npcName, npcOccupation, rng);
        } else {
            return _generateFlavorText(town, kingdom, npc, npcName, npcOccupation, npcGender, rng);
        }
    }

    function _generateUsefulInfo(town, kingdom, npc, npcName, npcOccupation, rng) {
        var towns = Engine.getTowns ? Engine.getTowns() : [];
        var infoType = rng.randInt(0, 7);

        switch (infoType) {
            case 0: // High price tip
            case 1: {
                var otherTowns = towns.filter(function(t) { return t.id !== town.id && t.market && t.market.prices; });
                if (otherTowns.length === 0) break;
                var tipTown = otherTowns[rng.randInt(0, otherTowns.length - 1)];
                var resources = Object.keys(tipTown.market.prices);
                if (resources.length === 0) break;
                var tipRes = resources[rng.randInt(0, resources.length - 1)];
                var tipPrice = tipTown.market.prices[tipRes];
                var baseRes = Engine.findResourceById ? Engine.findResourceById(tipRes) : null;
                var basePrice = baseRes ? baseRes.basePrice : 10;
                var resName = baseRes ? baseRes.name : tipRes;
                if (tipPrice > basePrice * 1.8) {
                    return { success: true, type: 'useful', icon: '📈', speaker: npcName, occupation: npcOccupation,
                        message: '"I heard ' + resName + ' is selling for ' + Math.round(tipPrice) + 'g in ' + tipTown.name + '! Much higher than usual. Could be a good chance to sell."' };
                } else if (tipPrice < basePrice * 0.6) {
                    return { success: true, type: 'useful', icon: '📉', speaker: npcName, occupation: npcOccupation,
                        message: '"Word is ' + resName + ' is dirt cheap in ' + tipTown.name + ' — only ' + Math.round(tipPrice) + 'g. Might be worth buying some."' };
                }
                // Fall through to next case if price isn't noteworthy
            }
            case 2: { // Elite merchant sighting
                var elites = [];
                for (var ei = 0; ei < towns.length; ei++) {
                    var ePeople = Engine.getPeopleCached ? Engine.getPeopleCached(towns[ei].id) : [];
                    for (var ej = 0; ej < ePeople.length; ej++) {
                        if (ePeople[ej].isEliteMerchant && ePeople[ej].alive) elites.push({ person: ePeople[ej], town: towns[ei] });
                    }
                }
                if (elites.length > 0) {
                    var em = elites[rng.randInt(0, elites.length - 1)];
                    return { success: true, type: 'useful', icon: '💎', speaker: npcName, occupation: npcOccupation,
                        message: '"The famous merchant ' + em.person.firstName + ' ' + em.person.lastName + ' was spotted in ' + em.town.name + ' recently. ' + (em.person.sex === 'F' ? 'She' : 'He') + '\'s one of the wealthiest traders in the realm."' };
                }
                break;
            }
            case 3: { // King rumor
                if (kingdom && kingdom.king) {
                    var kingPerson = Engine.findPerson ? Engine.findPerson(kingdom.king) : null;
                    var kingName = kingPerson ? (kingPerson.firstName + ' ' + kingPerson.lastName) : 'the king';
                    var greed = kingdom.kingPersonality ? kingdom.kingPersonality.greed : null;
                    if (greed === 'corrupt') {
                        return { success: true, type: 'useful', icon: '👑', speaker: npcName, occupation: npcOccupation,
                            message: '"Be careful around here. ' + kingName + ' is known to be corrupt. Taxes keep rising and the people suffer. Watch out for forced requisitions."' };
                    } else if (greed === 'generous') {
                        return { success: true, type: 'useful', icon: '👑', speaker: npcName, occupation: npcOccupation,
                            message: '"' + kingName + ' is a fair and generous ruler. Trade is good here, and the people are well-treated."' };
                    } else {
                        return { success: true, type: 'useful', icon: '👑', speaker: npcName, occupation: npcOccupation,
                            message: '"' + kingName + ' rules ' + kingdom.name + ' with a steady hand. Not the worst monarch we\'ve had."' };
                    }
                }
                break;
            }
            case 4: { // War intel
                var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
                var warIds = Object.keys(activeWars);
                if (warIds.length > 0) {
                    var war = activeWars[warIds[rng.randInt(0, warIds.length - 1)]];
                    if (war && war.active !== false) {
                        var kA = Engine.findKingdom(war.kingdomA);
                        var kB = Engine.findKingdom(war.kingdomB);
                        if (kA && kB) {
                            return { success: true, type: 'useful', icon: '⚔️', speaker: npcName, occupation: npcOccupation,
                                message: '"The war between ' + kA.name + ' and ' + kB.name + ' rages on. Military goods are in high demand. Dangerous times, but profitable for brave merchants."' };
                        }
                    }
                }
                break;
            }
            case 5: { // Supply shortage tip
                var shortages = [];
                for (var resId in town.market.supply) {
                    var demand = town.market.demand ? (town.market.demand[resId] || 0) : 0;
                    var supply = town.market.supply[resId] || 0;
                    if (demand > 0 && supply < demand * 0.3) {
                        var sRes = Engine.findResourceById ? Engine.findResourceById(resId) : null;
                        if (sRes) shortages.push(sRes.name);
                    }
                }
                if (shortages.length > 0) {
                    var shortage = shortages[rng.randInt(0, shortages.length - 1)];
                    return { success: true, type: 'useful', icon: '📦', speaker: npcName, occupation: npcOccupation,
                        message: '"We\'re running low on ' + shortage + ' here in ' + town.name + '. Anyone who brings some could make good coin."' };
                }
                break;
            }
            case 6: { // Bandit warning
                var roads = Engine.getRoads ? Engine.getRoads() : [];
                var dangerousRoads = [];
                for (var ri = 0; ri < roads.length; ri++) {
                    if ((roads[ri].banditThreat || 0) > 30 && (roads[ri].townA === town.id || roads[ri].townB === town.id)) {
                        var otherTownId = roads[ri].townA === town.id ? roads[ri].townB : roads[ri].townA;
                        var otherT = Engine.findTown(otherTownId);
                        if (otherT) dangerousRoads.push(otherT.name);
                    }
                }
                if (dangerousRoads.length > 0) {
                    var dangerDest = dangerousRoads[rng.randInt(0, dangerousRoads.length - 1)];
                    return { success: true, type: 'useful', icon: '🏴‍☠️', speaker: npcName, occupation: npcOccupation,
                        message: '"Watch yourself on the road to ' + dangerDest + '. Bandits have been hitting caravans hard. Hire guards if you can."' };
                }
                break;
            }
            case 7: { // Law tip
                if (kingdom && kingdom.laws && kingdom.laws.specialLaws && kingdom.laws.specialLaws.length > 0) {
                    var law = kingdom.laws.specialLaws[rng.randInt(0, kingdom.laws.specialLaws.length - 1)];
                    return { success: true, type: 'useful', icon: '📜', speaker: npcName, occupation: npcOccupation,
                        message: '"Did you know about the ' + (law.name || law.id) + ' law here? ' + (law.desc || 'Keep it in mind when doing business.') + '"' };
                }
                break;
            }
        }

        // Fallback to flavor text if useful info generation failed
        return _generateFlavorText(town, kingdom, npc, npcName, npcOccupation, npc ? (npc.sex === 'F' ? 'she' : 'he') : 'they', rng);
    }

    function _generateFlavorText(town, kingdom, npc, npcName, npcOccupation, npcGender, rng) {
        var townName = town.name;
        var kingdomName = kingdom ? kingdom.name : 'the realm';
        var season = Engine.getSeason ? Engine.getSeason() : 'spring';
        var happiness = town.happiness || 50;

        var FLAVOR_TEXTS = [
            // Weather / season
            '"' + (season === 'winter' ? 'Cold enough to freeze the river solid! Stay warm, friend.' : season === 'summer' ? 'Hot as a forge today! I could use a cold ale.' : season === 'spring' ? 'The flowers are blooming nicely this year. Good omen for the harvest.' : 'The leaves are turning. Winter will be upon us soon.') + '"',
            // Town life
            '"' + townName + ' has been my home all my life. It\'s not much, but it\'s honest."',
            '"The market was busy today. Lots of merchants coming through."',
            '"I work at the ' + (rng.chance(0.5) ? 'bakery' : 'smithy') + '. Honest work for honest pay."',
            '"Have you tried the ale at the inn? Best in ' + kingdomName + ', I say!"',
            '"My ' + (rng.chance(0.5) ? 'grandfather' : 'grandmother') + ' used to tell stories of dragons in these parts. Nonsense, of course."',
            // Occupation-specific
            '"' + (npcOccupation === 'farmer' ? 'The soil here is rich. Good for wheat and vegetables.' : npcOccupation === 'craftsman' ? 'I\'ve been crafting since I was a boy. There\'s pride in good work.' : npcOccupation === 'merchant' ? 'Trade is the lifeblood of any town. Without it, we\'d all starve.' : npcOccupation === 'soldier' ? 'We keep the peace here. Bandits think twice before coming to ' + townName + '.' : 'Life goes on, same as ever. Nothing much changes around here.') + '"',
            // Mood based on town happiness
            '"' + (happiness > 70 ? 'Times are good! Prosperity for all, the king says.' : happiness > 40 ? 'Can\'t complain, I suppose. Could be worse.' : 'Hard times, friend. Prices keep going up and wages stay the same.') + '"',
            // Random musings
            '"I saw a fox chasing a chicken this morning. Nature\'s comedy, I suppose."',
            '"My neighbor\'s cow got loose again. Third time this month!"',
            '"They say a traveling bard passed through last week. Wish I\'d seen the show."',
            '"The children have been playing knights and dragons all week. Brings back memories."',
            '"I hear the fisherman pulled up something strange from the river. Probably just an old boot."',
            // Port-specific
            town.isPort ? '"The ships come and go. I love watching them from the docks."' : '"I\'ve never seen the sea. Maybe one day."',
            // Religious / philosophical
            '"The priests say we should be grateful for what we have. Easy for them to say."',
            '"An honest day\'s work. That\'s all any of us can ask for."',
            '"My ' + (rng.chance(0.5) ? 'daughter' : 'son') + ' wants to become a merchant someday. Ambitious little one."',
        ];

        var text = FLAVOR_TEXTS[rng.randInt(0, FLAVOR_TEXTS.length - 1)];

        return { success: true, type: 'flavor', icon: '💬', speaker: npcName, occupation: npcOccupation, message: text };
    }

    // ── Thirst System ──

    function tickThirst() {
        if (!player.alive) return;

        var injDebuffs = getInjuryDebuffs();
        var thirstDecay = THIRST_CONFIG.DECAY_PER_DAY * (injDebuffs.thirstRate || 1.0);
        player.thirst = Math.max(0, (player.thirst != null ? player.thirst : THIRST_CONFIG.START) - thirstDecay);

        if (player.townId && !player.traveling) {
            // Military soldiers get water from the kingdom — skip auto-buy
            if (!player.militaryActive) {
            var town = Engine.findTown(player.townId);
            if (town && player.thirst < 60) {
                // Try to auto-buy beverages from market
                for (var bi = 0; bi < THIRST_CONFIG.BEVERAGE_TYPES.length && player.thirst < 80; bi++) {
                    var bevId = THIRST_CONFIG.BEVERAGE_TYPES[bi];
                    var supply = (town.market.supply[bevId] || 0);
                    var price = town.market.prices[bevId] || 2;
                    if (supply > 0 && player.gold >= price) {
                        town.market.supply[bevId]--;
                        player.gold -= price;
                        logFinance(-price, 'food_drink', 'Bought food/drink');
                        var restore = THIRST_CONFIG.BEVERAGE_RESTORE[bevId] || 20;
                        player.thirst = Math.min(THIRST_CONFIG.MAX, player.thirst + restore);
                        // Apply beverage effects
                        var effects = THIRST_CONFIG.BEVERAGE_EFFECTS[bevId];
                        if (effects && effects.happiness && player.happiness != null) {
                            player.happiness = Math.min(100, player.happiness + effects.happiness);
                        }
                    }
                }
            }
            } // end if not military
        } else if (player.traveling) {
            // Drink from inventory while traveling
            if (player.thirst < 50) {
                for (var ti = 0; ti < THIRST_CONFIG.BEVERAGE_TYPES.length; ti++) {
                    var drinkId = THIRST_CONFIG.BEVERAGE_TYPES[ti];
                    if ((player.inventory[drinkId] || 0) > 0) {
                        player.inventory[drinkId]--;
                        if (player.inventory[drinkId] <= 0) delete player.inventory[drinkId];
                        player.thirst = Math.min(THIRST_CONFIG.MAX, player.thirst + (THIRST_CONFIG.BEVERAGE_RESTORE[drinkId] || 20));
                        break;
                    }
                }
                if (player.thirst <= 0) {
                    if (typeof UI !== 'undefined' && UI.toast) {
                        UI.toast('⚠️ You are dehydrated! Find water soon!', 'danger');
                    }
                }
            }
        }

        // Dehydration effects
        if (player.thirst <= THIRST_CONFIG.DEHYDRATED_THRESHOLD) {
            // Speed reduction handled in travel tick
            // Energy drain from dehydration
            if (player.thirst <= 0) {
                player.energy = Math.max(0, (player.energy || 0) - 3);
                // Health loss from severe dehydration
                if (!player._lastDehydrateTick || Engine.getDay() > player._lastDehydrateTick) {
                    player._lastDehydrateTick = Engine.getDay();
                    player.health = Math.max(0, (player.health || 100) - 2);
                    if (player.health <= 0 && player.alive) {
                        if (typeof UI !== 'undefined' && UI.toast) {
                            UI.toast('💀 You have died of dehydration!', 'danger');
                        }
                        if (typeof handlePlayerDeath === 'function') handlePlayerDeath('dehydration');
                    }
                }
            } else {
                // Mild dehydration — reduced energy
                player.energy = Math.max(0, (player.energy || 0) - 1);
            }
        }
    }

    function getThirstDebuffs() {
        if ((player.thirst != null ? player.thirst : THIRST_CONFIG.START) > THIRST_CONFIG.DEHYDRATED_THRESHOLD) return null;
        return {
            travelSpeed: -THIRST_CONFIG.DEHYDRATED_SPEED_PENALTY,
            workPay: -THIRST_CONFIG.DEHYDRATED_WORK_PENALTY,
        };
    }

    // ── Food & Drink Supply Helpers ──

    function getFoodSupply() {
        var total = 0;
        var items = [];
        var allTypes = HUNGER_CONFIG.FOOD_TYPES.concat(HUNGER_CONFIG.RAW_FOOD_TYPES);
        for (var i = 0; i < allTypes.length; i++) {
            var qty = player.inventory[allTypes[i]] || 0;
            if (qty > 0) {
                var restore = HUNGER_CONFIG.RAW_FOOD_TYPES.indexOf(allTypes[i]) !== -1 ? HUNGER_CONFIG.RAW_FOOD_RESTORE : HUNGER_CONFIG.FOOD_RESTORE;
                items.push({ id: allTypes[i], qty: qty, restore: restore });
                total += qty;
            }
        }
        // Estimate days: each food item restores X hunger, decay is Y per day
        var totalRestore = 0;
        for (var j = 0; j < items.length; j++) totalRestore += items[j].qty * items[j].restore;
        var daysEstimate = HUNGER_CONFIG.DECAY_PER_DAY > 0 ? Math.floor(totalRestore / HUNGER_CONFIG.DECAY_PER_DAY) : 999;
        return { total: total, items: items, daysEstimate: daysEstimate };
    }

    function getDrinkSupply() {
        var total = 0;
        var items = [];
        for (var i = 0; i < THIRST_CONFIG.BEVERAGE_TYPES.length; i++) {
            var bev = THIRST_CONFIG.BEVERAGE_TYPES[i];
            var qty = player.inventory[bev] || 0;
            if (qty > 0) {
                var restore = THIRST_CONFIG.BEVERAGE_RESTORE[bev] || 20;
                items.push({ id: bev, qty: qty, restore: restore });
                total += qty;
            }
        }
        var totalRestore = 0;
        for (var j = 0; j < items.length; j++) totalRestore += items[j].qty * items[j].restore;
        var daysEstimate = THIRST_CONFIG.DECAY_PER_DAY > 0 ? Math.floor(totalRestore / THIRST_CONFIG.DECAY_PER_DAY) : 999;
        return { total: total, items: items, daysEstimate: daysEstimate };
    }

    function eatUntilFull() {
        if (!player.alive) return { success: false, message: 'Cannot eat.' };
        if (player.hunger >= HUNGER_CONFIG.MAX) return { success: false, message: 'Already full.' };
        var eaten = 0;
        var allTypes = HUNGER_CONFIG.FOOD_TYPES.concat(HUNGER_CONFIG.RAW_FOOD_TYPES);
        while (player.hunger < HUNGER_CONFIG.MAX) {
            var found = false;
            for (var i = 0; i < allTypes.length; i++) {
                var fid = allTypes[i];
                if ((player.inventory[fid] || 0) > 0) {
                    player.inventory[fid]--;
                    if (player.inventory[fid] <= 0) delete player.inventory[fid];
                    var restore = HUNGER_CONFIG.RAW_FOOD_TYPES.indexOf(fid) !== -1 ? HUNGER_CONFIG.RAW_FOOD_RESTORE : HUNGER_CONFIG.FOOD_RESTORE;
                    player.hunger = Math.min(HUNGER_CONFIG.MAX, player.hunger + restore);
                    eaten++;
                    found = true;
                    break;
                }
            }
            if (!found) break;
        }
        if (eaten === 0) return { success: false, message: 'No food in inventory.' };
        return { success: true, message: 'Ate ' + eaten + ' item' + (eaten > 1 ? 's' : '') + '. Hunger: ' + Math.floor(player.hunger) };
    }

    function drinkUntilFull() {
        if (!player.alive) return { success: false, message: 'Cannot drink.' };
        if (player.thirst >= THIRST_CONFIG.MAX) return { success: false, message: 'Already quenched.' };
        var drunk = 0;
        while (player.thirst < THIRST_CONFIG.MAX) {
            var found = false;
            for (var i = 0; i < THIRST_CONFIG.BEVERAGE_TYPES.length; i++) {
                var bid = THIRST_CONFIG.BEVERAGE_TYPES[i];
                if ((player.inventory[bid] || 0) > 0) {
                    player.inventory[bid]--;
                    if (player.inventory[bid] <= 0) delete player.inventory[bid];
                    var restore = THIRST_CONFIG.BEVERAGE_RESTORE[bid] || 20;
                    player.thirst = Math.min(THIRST_CONFIG.MAX, player.thirst + restore);
                    // Apply beverage effects
                    var effects = THIRST_CONFIG.BEVERAGE_EFFECTS[bid];
                    if (effects && effects.happiness && player.happiness != null) {
                        player.happiness = Math.min(100, player.happiness + effects.happiness);
                    }
                    drunk++;
                    found = true;
                    break;
                }
            }
            if (!found) break;
        }
        if (drunk === 0) return { success: false, message: 'No drinks in inventory.' };
        return { success: true, message: 'Drank ' + drunk + ' item' + (drunk > 1 ? 's' : '') + '. Thirst: ' + Math.floor(player.thirst) };
    }

    function drawWaterFromWell(townId) {
        var tid = townId || player.townId;
        if (player.traveling) return { success: false, message: 'Cannot draw water while traveling.' };
        var town = Engine.findTown(tid);
        if (!town) return { success: false, message: 'No town found.' };

        // Find an active (non-depleted) well
        var activeWell = null;
        if (town.buildings) {
            for (var i = 0; i < town.buildings.length; i++) {
                var b = town.buildings[i];
                if ((b.type === 'well' && !b.depleted) || b.type === 'cistern') {
                    activeWell = b;
                    break;
                }
            }
        }
        if (!activeWell) return { success: false, message: 'No active well in ' + (town.name || 'this town') + '. All wells have run dry!' };

        // Check kingdom law on well water
        var kingdom = Engine.findKingdom(town.kingdomId);
        var isFree = kingdom && kingdom.laws && kingdom.laws.freeWellWater !== false; // default true
        var cost = isFree ? 0 : 1;

        if (cost > 0 && player.gold < cost) {
            return { success: false, message: 'Well water costs ' + cost + 'g in this kingdom. You can\'t afford it.' };
        }

        // Check rep — need at least non-hostile rep to use the well
        var townKingdomId = town.kingdomId;
        var townRep = player.reputation && townKingdomId ? (player.reputation[townKingdomId] || 0) : 0;
        if (townRep < -30) {
            return { success: false, message: 'The townsfolk won\'t let you near the well. Your reputation is too low.' };
        }

        // Pay cost
        if (cost > 0) {
            player.gold -= cost;
            player.stats.totalGoldSpent = (player.stats.totalGoldSpent || 0) + cost;
        }

        // Advance time
        if (typeof Game !== 'undefined' && Game.advanceTicks) Game.advanceTicks(THIRST_CONFIG.WELL_DRAW_TICKS);

        // Deduct from well water supply
        var drawAmount = THIRST_CONFIG.WELL_DRAW_AMOUNT;
        if (activeWell.type === 'well' && activeWell.waterRemaining != null) {
            var actualDraw = Math.min(drawAmount, activeWell.waterRemaining);
            activeWell.waterRemaining -= actualDraw;
            if (activeWell.waterRemaining <= 0) {
                activeWell.waterRemaining = 0;
                activeWell.depleted = true;
            }
        }

        // Give water
        player.inventory.water = (player.inventory.water || 0) + drawAmount;

        // Also drink immediately if thirsty
        if (player.thirst < 70) {
            player.thirst = Math.min(THIRST_CONFIG.MAX, player.thirst + THIRST_CONFIG.BEVERAGE_RESTORE.water);
        }

        // Build status message with water remaining info
        var costMsg = isFree ? '(free well water)' : '(-' + cost + 'g)';
        var waterInfo = '';
        if (activeWell.type === 'well' && activeWell.waterCapacity) {
            var pct = Math.round((activeWell.waterRemaining / activeWell.waterCapacity) * 100);
            waterInfo = ' Well: ' + Math.floor(activeWell.waterRemaining).toLocaleString() + '/' + activeWell.waterCapacity.toLocaleString() + ' (' + pct + '%)';
        }
        return { success: true, message: '💧 Drew ' + drawAmount + ' water from the well. ' + costMsg + waterInfo };
    }

    // ========================================================
    // §12M  WILDERNESS OUTPOST SYSTEM (Player)
    // ========================================================

    /**
     * Found a wilderness outpost. Player must be traveling or at a road between towns.
     * @param {string} name - Name for the outpost
     * @returns {{ success: boolean, message: string }}
     */
    function foundPlayerOutpost(name) {
        var cfg = CONFIG.OUTPOST_CONFIG;
        if (!name || name.trim().length === 0) return { success: false, message: 'Outpost needs a name.' };

        // Cost check
        if (player.gold < cfg.foundingCost) {
            return { success: false, message: 'Need ' + cfg.foundingCost + 'g to establish an outpost. You have ' + Math.floor(player.gold) + 'g.' };
        }

        // Material check
        var matMissing = [];
        for (var matId in cfg.foundingMaterials) {
            var needed = cfg.foundingMaterials[matId];
            var has = player.inventory[matId] || 0;
            if (has < needed) matMissing.push(needed + ' ' + matId + ' (have ' + has + ')');
        }
        if (matMissing.length > 0) {
            return { success: false, message: 'Missing materials: ' + matMissing.join(', ') };
        }

        // Determine outpost position
        var ox, oy;
        if (player.traveling && player.travelData) {
            // Use current travel position (interpolated)
            var from = Engine.findTown(player.travelData.fromTownId);
            var to = Engine.findTown(player.travelData.toTownId);
            if (from && to) {
                var progress = player.travelData.progress || 0.5;
                ox = Math.floor(from.x + (to.x - from.x) * progress);
                oy = Math.floor(from.y + (to.y - from.y) * progress);
            } else {
                var town = Engine.findTown(player.townId);
                ox = town ? town.x + 30 : 100;
                oy = town ? town.y + 30 : 100;
            }
        } else {
            // Use current town position offset
            var curTown = Engine.findTown(player.townId);
            if (!curTown) return { success: false, message: 'Cannot determine location for outpost.' };
            var rng = Engine.getRng();
            ox = curTown.x + (rng ? rng.randInt(-60, 60) : 30);
            oy = curTown.y + (rng ? rng.randInt(-60, 60) : 30);
        }

        // Deduct costs
        player.gold -= cfg.foundingCost;
        player.stats.totalGoldSpent = (player.stats.totalGoldSpent || 0) + cfg.foundingCost;
        for (var matId2 in cfg.foundingMaterials) {
            player.inventory[matId2] = (player.inventory[matId2] || 0) - cfg.foundingMaterials[matId2];
            if (player.inventory[matId2] <= 0) delete player.inventory[matId2];
        }

        // Determine kingdom (nearest to outpost location)
        var result = Engine.foundOutpost({
            founderId: player.id || 'player',
            founderType: 'player',
            x: ox,
            y: oy,
            name: name.trim(),
        });

        if (result.success && result.outpost) {
            // Track player outposts
            if (!player.outposts) player.outposts = [];
            player.outposts.push({
                townId: result.outpost.id,
                name: result.outpost.name,
                foundedDay: Engine.getDay(),
            });
        }

        return result;
    }

    /**
     * Get player's outposts with status info.
     */
    function getPlayerOutposts() {
        if (!player.outposts || player.outposts.length === 0) return [];
        var outposts = [];
        for (var i = 0; i < player.outposts.length; i++) {
            var po = player.outposts[i];
            var town = Engine.findTown(po.townId);
            if (!town) continue;
            outposts.push({
                townId: town.id,
                name: town.name,
                category: town.category,
                buildings: town.buildings.length,
                maxBuildings: town.maxBuildingSlots || 4,
                workers: town.hiredWorkers || 0,
                guards: town.hiredGuards || 0,
                walls: town.walls || 0,
                prosperity: town.prosperity || 0,
                population: town.population || 0,
                dailyCost: (town._dailyMaintenanceDue || CONFIG.OUTPOST_CONFIG.dailyMaintenanceCost),
                isOutpost: town.isOutpost,
                annexed: town.annexed || false,
                abandoned: town.abandoned || false,
                foundedDay: po.foundedDay,
            });
        }
        return outposts;
    }

    /**
     * Pay daily maintenance for player outposts. Called from player tick.
     */
    function payOutpostMaintenance() {
        if (!player.outposts || player.outposts.length === 0) return;
        var cfg = CONFIG.OUTPOST_CONFIG;

        for (var i = 0; i < player.outposts.length; i++) {
            var po = player.outposts[i];
            var town = Engine.findTown(po.townId);
            if (!town || !town.isOutpost || town.abandoned || town.destroyed) continue;

            var dailyCost = cfg.dailyMaintenanceCost +
                (town.hiredWorkers || 0) * cfg.workerWagePerDay +
                (town.hiredGuards || 0) * cfg.guardCostPerDay;

            if (player.gold >= dailyCost) {
                player.gold -= dailyCost;
                player.stats.totalGoldSpent = (player.stats.totalGoldSpent || 0) + dailyCost;
                town.maintenancePaid = true;
                town.lastMaintenanceDay = Engine.getDay();
            } else {
                town.maintenancePaid = false;
                // Warn player
                Engine.logEvent('⚠️ You cannot afford ' + dailyCost + 'g maintenance for outpost "' + town.name + '"!');
            }

            // Player outpost abandonment
            if (!town.maintenancePaid) {
                var daysSince = Engine.getDay() - (town.lastMaintenanceDay || town.foundedDay || 0);
                if (daysSince >= cfg.abandonDaysNoMaintenance) {
                    town.abandoned = true;
                    town.abandonedDay = Engine.getDay();
                    Engine.logEvent('💀 Your outpost "' + town.name + '" has been abandoned due to ' + daysSince + ' days without maintenance!');
                    // Remove from player tracking
                    player.outposts.splice(i, 1);
                    i--;
                }
            }
        }
    }

    /**
     * Hire or dismiss workers/guards at a player outpost.
     */
    function manageOutpostStaff(townId, action, type) {
        var town = Engine.findTown(townId);
        if (!town || !town.isOutpost) return { success: false, message: 'Not an outpost.' };
        if (town.founderId !== (player.id || 'player')) return { success: false, message: 'Not your outpost.' };
        var cfg = CONFIG.OUTPOST_CONFIG;

        if (type === 'worker') {
            if (action === 'hire') {
                if ((town.hiredWorkers || 0) >= cfg.maxHiredWorkers) return { success: false, message: 'Maximum workers reached (' + cfg.maxHiredWorkers + ').' };
                town.hiredWorkers = (town.hiredWorkers || 0) + 1;
                return { success: true, message: '👷 Hired a worker. (' + town.hiredWorkers + '/' + cfg.maxHiredWorkers + ')' };
            } else {
                if ((town.hiredWorkers || 0) <= 0) return { success: false, message: 'No workers to dismiss.' };
                town.hiredWorkers--;
                return { success: true, message: '👋 Dismissed a worker. (' + town.hiredWorkers + '/' + cfg.maxHiredWorkers + ')' };
            }
        } else if (type === 'guard') {
            if (action === 'hire') {
                if ((town.hiredGuards || 0) >= cfg.maxGuards) return { success: false, message: 'Maximum guards reached (' + cfg.maxGuards + ').' };
                town.hiredGuards = (town.hiredGuards || 0) + 1;
                return { success: true, message: '🛡️ Hired a guard. (' + town.hiredGuards + '/' + cfg.maxGuards + ')' };
            } else {
                if ((town.hiredGuards || 0) <= 0) return { success: false, message: 'No guards to dismiss.' };
                town.hiredGuards--;
                return { success: true, message: '👋 Dismissed a guard. (' + town.hiredGuards + '/' + cfg.maxGuards + ')' };
            }
        }
        return { success: false, message: 'Unknown staff type.' };
    }

    // ========================================================
    // §12L  RETAIL & SERVICE BUILDING SYSTEM
    // ========================================================

    function getRetailBuildings() {
        if (!player.buildings) return [];
        return player.buildings.filter(function(b) {
            var bt = findBuildingType(b.type);
            return bt && bt.retailConfig;
        });
    }

    function findBuildingType(typeId) {
        for (var key in BUILDING_TYPES) {
            if (BUILDING_TYPES[key].id === typeId) return BUILDING_TYPES[key];
        }
        return null;
    }

    function stockRetailBuilding(buildingId, resourceId, quantity) {
        if (quantity != null) { quantity = Number(quantity); if (!isFinite(quantity) || quantity <= 0) return { success: false, message: 'Invalid quantity.' }; }
        var bld = (player.buildings || []).find(function(b) { return b.id === buildingId; });
        if (!bld) return { success: false, message: 'Building not found.' };
        var bt = findBuildingType(bld.type);
        if (!bt || !bt.retailConfig) return { success: false, message: 'This building is not a retail building.' };

        // Check if this good is accepted
        if (bt.retailConfig.acceptsGoods.indexOf(resourceId) === -1) {
            return { success: false, message: 'This shop doesn\'t sell ' + resourceId + '.' };
        }

        // Check player inventory
        var available = player.inventory[resourceId] || 0;
        if (available <= 0) return { success: false, message: 'You have no ' + resourceId + ' to stock.' };
        var qty = Math.min(quantity || available, available);

        // Check stock capacity
        bld.retailStock = bld.retailStock || {};
        var currentTotal = 0;
        for (var k in bld.retailStock) { currentTotal += (bld.retailStock[k] || 0); }
        var maxStock = (bt.retailConfig.maxStock || 50) * (bld.level || 1);
        var canAdd = Math.min(qty, maxStock - currentTotal);
        if (canAdd <= 0) return { success: false, message: 'Shop is fully stocked! (Capacity: ' + maxStock + ')' };

        // Transfer from inventory to shop
        player.inventory[resourceId] -= canAdd;
        if (player.inventory[resourceId] <= 0) delete player.inventory[resourceId];
        bld.retailStock[resourceId] = (bld.retailStock[resourceId] || 0) + canAdd;

        var res = findResource(resourceId);
        return { success: true, message: '📦 Stocked ' + canAdd + ' ' + (res ? res.name : resourceId) + ' in your ' + (bt.name || 'shop') + '.' };
    }

    function unstockRetailBuilding(buildingId, resourceId, quantity) {
        if (quantity != null) { quantity = Number(quantity); if (!isFinite(quantity) || quantity <= 0) return { success: false, message: 'Invalid quantity.' }; }
        var bld = (player.buildings || []).find(function(b) { return b.id === buildingId; });
        if (!bld) return { success: false, message: 'Building not found.' };
        bld.retailStock = bld.retailStock || {};
        var available = bld.retailStock[resourceId] || 0;
        if (available <= 0) return { success: false, message: 'No ' + resourceId + ' in this shop.' };
        var qty = Math.min(quantity || available, available);

        bld.retailStock[resourceId] -= qty;
        if (bld.retailStock[resourceId] <= 0) delete bld.retailStock[resourceId];
        player.inventory[resourceId] = (player.inventory[resourceId] || 0) + qty;

        var res = findResource(resourceId);
        return { success: true, message: '📤 Withdrew ' + qty + ' ' + (res ? res.name : resourceId) + ' from shop.' };
    }

    function collectRetailRevenue(buildingId) {
        var bld = (player.buildings || []).find(function(b) { return b.id === buildingId; });
        if (!bld) return { success: false, message: 'Building not found.' };
        var revenue = bld.retailRevenue || 0;
        if (revenue <= 0) return { success: false, message: 'No revenue to collect.' };
        player.gold += revenue;
        player.stats.totalGoldEarned = (player.stats.totalGoldEarned || 0) + revenue;
        bld.retailRevenue = 0;
        return { success: true, message: '💰 Collected ' + Math.floor(revenue) + 'g in retail revenue!' };
    }

    function collectAllRetailRevenue() {
        var total = 0;
        var buildings = getRetailBuildings();
        for (var i = 0; i < buildings.length; i++) {
            var rev = buildings[i].retailRevenue || 0;
            if (rev > 0) {
                total += rev;
                buildings[i].retailRevenue = 0;
            }
        }
        if (total <= 0) return { success: false, message: 'No retail revenue to collect.' };
        player.gold += total;
        player.stats.totalGoldEarned = (player.stats.totalGoldEarned || 0) + total;
        return { success: true, message: '💰 Collected ' + Math.floor(total) + 'g total retail revenue from ' + buildings.length + ' shops!' };
    }

    function getRetailBuildingStatus(buildingId) {
        var bld = (player.buildings || []).find(function(b) { return b.id === buildingId; });
        if (!bld) return null;
        var bt = findBuildingType(bld.type);
        if (!bt || !bt.retailConfig) return null;

        bld.retailStock = bld.retailStock || {};
        var stockTotal = 0;
        var stockItems = [];
        for (var k in bld.retailStock) {
            if (bld.retailStock[k] > 0) {
                var res = findResource(k);
                stockItems.push({ id: k, name: res ? res.name : k, qty: bld.retailStock[k], icon: res ? res.icon : '📦' });
                stockTotal += bld.retailStock[k];
            }
        }
        var maxStock = (bt.retailConfig.maxStock || 50) * (bld.level || 1);
        var markup = getRetailMarkup(bld);

        return {
            building: bld,
            type: bt,
            stock: stockItems,
            stockTotal: stockTotal,
            maxStock: maxStock,
            revenue: bld.retailRevenue || 0,
            totalEarned: bld.retailTotalEarned || 0,
            totalSold: bld.retailTotalSold || 0,
            customersToday: bld.retailCustomersToday || 0,
            maxCustomers: (bt.retailConfig.maxCustomersPerDay || 5) * (bld.level || 1),
            markup: markup,
            acceptsGoods: bt.retailConfig.acceptsGoods,
        };
    }

    function getRetailMarkup(bld) {
        var bt = findBuildingType(bld.type);
        if (!bt || !bt.retailConfig) return 1.0;
        var base = bt.retailConfig.baseMarkup || 1.2;
        var upgradeBonus = (bt.retailConfig.upgradeMarkupBonus || 0.1) * ((bld.level || 1) - 1);
        var max = bt.retailConfig.maxMarkup || 2.0;
        return Math.min(max, base + upgradeBonus);
    }

    function tickRetailBuildings() {
        if (!player.buildings || !player.alive) return;
        var rng = Engine.getRng();
        if (!rng) return;

        for (var bi = 0; bi < player.buildings.length; bi++) {
            var bld = player.buildings[bi];
            var bt = findBuildingType(bld.type);
            if (!bt || !bt.retailConfig) continue;

            // Reset daily customer count
            bld.retailCustomersToday = 0;
            bld.retailStock = bld.retailStock || {};
            bld.retailRevenue = bld.retailRevenue || 0;
            bld.retailTotalEarned = bld.retailTotalEarned || 0;
            bld.retailTotalSold = bld.retailTotalSold || 0;

            // Need workers to operate
            var workerCount = Array.isArray(bld.workers) ? bld.workers.length : (bld.workers || 0);
            if (workerCount < (bt.workers || 1)) continue;

            var town = Engine.findTown(bld.townId);
            if (!town) continue;

            // Calculate max potential customers based on town pop and building level
            var maxCust = (bt.retailConfig.maxCustomersPerDay || 5) * (bld.level || 1);
            var popFactor = Math.min(2.0, (town.population || 50) / 100);
            maxCust = Math.floor(maxCust * popFactor);
            if (maxCust < 1) maxCust = 1;

            var markup = getRetailMarkup(bld);
            var motivation = bt.retailConfig.npcMotivation || 'need';

            // Kingdom tax info for this town
            var kingdom = Engine.findKingdom(town.kingdomId);
            var tariffRate = (kingdom && kingdom.laws && kingdom.laws.tradeTariff) || 0.05;

            var actualCustomers = 0;
            for (var ci = 0; ci < maxCust; ci++) {

                // ── NPC decides: market or shop? ──
                // Service buildings (clinic, bathhouse) always draw — no market alternative
                if (bt.retailConfig.serviceFee) {
                    var canServe = true;
                    var serviceCost = bt.retailConfig.consumesPerService || {};
                    for (var sRes in serviceCost) {
                        if ((bld.retailStock[sRes] || 0) < serviceCost[sRes]) { canServe = false; break; }
                    }
                    if (!canServe) continue;

                    // Base chance: service motivation
                    var serviceChance = 0.5;
                    if (motivation === 'health') {
                        var hasPlague = false;
                        if (typeof Engine !== 'undefined' && Engine.getActiveEvents) {
                            var evts = Engine.getActiveEvents ? Engine.getActiveEvents() : [];
                            hasPlague = evts.some(function(e) { return e.type === 'plague_disaster' && e.townId === bld.townId && e.active; });
                        }
                        serviceChance = hasPlague ? 0.9 : 0.4;
                    } else if (motivation === 'hygiene') {
                        serviceChance = 0.6;
                    }
                    if (!rng.chance(serviceChance)) continue;

                    // Consume service materials
                    for (var sRes2 in serviceCost) {
                        bld.retailStock[sRes2] -= serviceCost[sRes2];
                        if (bld.retailStock[sRes2] <= 0) delete bld.retailStock[sRes2];
                    }

                    var fee = bt.retailConfig.serviceFee * (bld.level || 1);
                    // Tax the service fee
                    var serviceTax = Math.floor(fee * tariffRate);
                    if (kingdom) kingdom.gold = (kingdom.gold || 0) + serviceTax;
                    var netFee = fee - serviceTax;

                    bld.retailRevenue += netFee;
                    bld.retailTotalEarned += netFee;
                    bld.retailTotalSold++;
                    actualCustomers++;
                    continue;
                }

                // ── Retail sale: NPC checks market first ──
                var stockKeys = Object.keys(bld.retailStock).filter(function(k) { return bld.retailStock[k] > 0; });
                if (stockKeys.length === 0) break; // shop empty

                // Pick a random stocked item the NPC might want
                var itemId = stockKeys[Math.floor(rng.random() * stockKeys.length)];
                var res = findResource(itemId);
                var marketPrice = town.market.prices[itemId] || (res ? res.basePrice : 5);
                var shopPrice = Math.round(marketPrice * markup);
                var marketSupply = town.market.supply[itemId] || 0;

                // NPC decision: buy from market or shop?
                var buyFromShop = false;
                var npcWealth = 20 + Math.floor(rng.random() * 80); // random NPC wealth 20-100g

                if (marketSupply <= 0) {
                    // Market out of stock — shop is only option
                    buyFromShop = npcWealth >= shopPrice;
                } else if (shopPrice <= marketPrice * 1.1) {
                    // Shop price competitive with market — might prefer shop for convenience
                    buyFromShop = rng.chance(0.4);
                } else if (npcWealth > shopPrice * 3) {
                    // Wealthy NPC doesn't care about markup
                    buyFromShop = rng.chance(0.5);
                } else {
                    // Shop is more expensive — NPC preference based on motivation
                    var prefChance = 0.15; // base: 15% prefer shop even at markup
                    if (motivation === 'happiness') {
                        // Tavern: people pay for the atmosphere
                        var happiness = town.happiness || 50;
                        prefChance = happiness < 40 ? 0.6 : happiness < 60 ? 0.35 : 0.2;
                    } else if (motivation === 'hunger') {
                        // Restaurant: prepared meals are worth more
                        prefChance = marketSupply < 30 ? 0.7 : 0.25;
                    } else if (motivation === 'luxury') {
                        // Jeweler: wealthy NPCs browse boutiques
                        var tc = town.category || 'town';
                        prefChance = tc === 'capital_city' ? 0.5 : tc === 'city' ? 0.35 : 0.15;
                    } else if (motivation === 'need') {
                        // General/clothing/armory: convenience factor
                        prefChance = marketSupply < 20 ? 0.5 : 0.2;
                    }
                    buyFromShop = rng.chance(prefChance) && npcWealth >= shopPrice;
                }

                if (!buyFromShop) continue;

                // Sale! Remove from stock, add revenue
                bld.retailStock[itemId]--;
                if (bld.retailStock[itemId] <= 0) delete bld.retailStock[itemId];

                // Kingdom tax on the sale
                var saleTax = Math.floor(shopPrice * tariffRate);
                if (kingdom) kingdom.gold = (kingdom.gold || 0) + saleTax;
                var netRevenue = shopPrice - saleTax;

                bld.retailRevenue += netRevenue;
                bld.retailTotalEarned += netRevenue;
                bld.retailTotalSold++;
                actualCustomers++;
            }

            bld.retailCustomersToday = actualCustomers;

            // Reputation bonus from sales
            if (actualCustomers > 0 && bt.retailConfig.repPerSale) {
                var repGain = actualCustomers * bt.retailConfig.repPerSale;
                addReputation(bld.townId, repGain);
            }

            // Plague reduction from bathhouse
            if (bt.retailConfig.plagueReduction && actualCustomers > 0) {
                bld.plagueReductionActive = true;
            }
        }
    }

    // ========================================================
    // §12K  WARTIME TRAVEL DANGER
    // ========================================================
    function hireArmedEscort(days) {
        days = Number(days);
        if (!days || !isFinite(days) || days <= 0) return { success: false, message: 'Invalid escort duration.' };
        days = Math.floor(days);
        var cost = days * CONFIG.WARTIME_ESCORT_COST_PER_DAY;
        if (player.gold < cost) return { success: false, message: 'Need ' + cost + 'g for ' + days + ' days of armed escort.' };
        player.gold -= cost;
        player.stats.totalGoldSpent += cost;
        player.armedEscort = { active: true, daysLeft: days };
        Engine.logEvent(player.fullName + ' hired an armed escort for ' + days + ' days (' + cost + 'g).');
        return { success: true, message: '⚔️ Armed escort hired for ' + days + ' days. (-' + cost + 'g)' };
    }

    // ========================================================
    // §12K-NEW  PLAYER ENCOUNTER SYSTEM (Bandits / Pirates / Wartime)
    // ========================================================

    function hirePersonalGuard() {
        if (!player.townId || player.traveling) return { success: false, message: 'Must be in a town to hire guards.' };
        var maxGuards = CONFIG.PLAYER_GUARD_MAX || 4;
        player.guards = player.guards || [];
        if (player.guards.length >= maxGuards) return { success: false, message: 'Already at maximum ' + maxGuards + ' guards.' };
        var cost = CONFIG.PLAYER_GUARD_HIRE_COST || 30;
        if (hasSkill('cheap_security')) cost = Math.floor(cost * 0.80);
        if (player.gold < cost) return { success: false, message: 'Need ' + cost + 'g to hire a guard.' };

        // Find a suitable NPC from the current town
        var townPeople = Engine.getPeople ? Engine.getPeople(player.townId) : [];
        var existingGuardIds = {};
        for (var gi = 0; gi < player.guards.length; gi++) {
            if (player.guards[gi].personId) existingGuardIds[player.guards[gi].personId] = true;
        }
        // Filter: alive, adult, not already a guard, not the player's spouse, not a child
        var candidates = [];
        for (var ci = 0; ci < townPeople.length; ci++) {
            var p = townPeople[ci];
            if (!p.alive || p.age < 18) continue;
            if (existingGuardIds[p.id]) continue;
            if (p.id === player.spouseId) continue;
            if (p.isPlayerGuard) continue;
            // Prefer unemployed or soldiers
            candidates.push(p);
        }
        if (candidates.length === 0) return { success: false, message: 'No one available to hire in this town.' };

        // Pick a candidate — prefer soldiers/unemployed
        var rng = Engine.getRng();
        var preferred = candidates.filter(function(c) {
            return c.occupation === 'soldier' || c.occupation === 'guard' || c.occupation === 'unemployed' || !c.occupation;
        });
        var chosen = preferred.length > 0 ? (rng.pick ? rng.pick(preferred) : preferred[Math.floor(rng.random() * preferred.length)])
            : (rng.pick ? rng.pick(candidates) : candidates[Math.floor(rng.random() * candidates.length)]);

        player.gold -= cost;
        logFinance(-cost, 'guards', 'Hired personal guard');

        // Mark NPC as player guard
        chosen.isPlayerGuard = true;
        chosen.previousOccupation = chosen.occupation;
        chosen.previousTownId = chosen.townId;
        chosen.occupation = 'player_guard';

        var guardName = (chosen.firstName || '') + (chosen.lastName ? ' ' + chosen.lastName : '');
        if (!guardName.trim()) guardName = 'Guard ' + (player.guards.length + 1);
        var guard = {
            id: 'guard_' + Date.now() + '_' + (rng ? rng.randInt(0, 9999) : Math.floor(Math.random() * 9999)),
            personId: chosen.id,
            name: guardName,
            hiredDay: Engine.getDay()
        };
        player.guards.push(guard);
        player.personalGuards = player.guards.length;
        Engine.logEvent('\uD83D\uDEE1\uFE0F Hired ' + guardName + ' as a personal guard for ' + cost + 'g. (' + player.guards.length + '/' + maxGuards + ')');
        return { success: true, message: '\uD83D\uDEE1\uFE0F ' + guardName + ' hired for ' + cost + 'g. (' + player.guards.length + '/' + maxGuards + ')', guard: guard };
    }

    function dismissPersonalGuard(guardId) {
        player.guards = player.guards || [];
        if (player.guards.length === 0) return { success: false, message: 'No guards to dismiss.' };
        var idx = -1;
        if (guardId) {
            for (var i = 0; i < player.guards.length; i++) {
                if (player.guards[i].id === guardId) { idx = i; break; }
            }
        }
        if (idx === -1) idx = player.guards.length - 1;
        var dismissed = player.guards[idx];
        var name = dismissed.name;

        // Return NPC to current town
        if (dismissed.personId && Engine.getPerson) {
            var npc = Engine.getPerson(dismissed.personId);
            if (npc && npc.alive) {
                npc.isPlayerGuard = false;
                npc.occupation = npc.previousOccupation || 'unemployed';
                npc.townId = player.townId || npc.previousTownId || npc.townId;
                delete npc.previousOccupation;
                delete npc.previousTownId;
            }
        }

        player.guards.splice(idx, 1);
        player.personalGuards = player.guards.length;
        Engine.logEvent('\uD83D\uDEE1\uFE0F Dismissed guard ' + name + '. (' + player.guards.length + '/' + (CONFIG.PLAYER_GUARD_MAX || 4) + ')');
        return { success: true, message: '\uD83D\uDEE1\uFE0F Dismissed ' + name + '. (' + player.guards.length + '/' + (CONFIG.PLAYER_GUARD_MAX || 4) + ')' };
    }

    function tickPersonalGuardWages() {
        player.guards = player.guards || [];
        if (player.guards.length === 0) return;

        // Sync guard NPC locations with player + remove dead guards
        for (var gi = player.guards.length - 1; gi >= 0; gi--) {
            var g = player.guards[gi];
            if (g.personId && Engine.getPerson) {
                var npc = Engine.getPerson(g.personId);
                if (!npc || !npc.alive) {
                    Engine.logEvent('💀 Your guard ' + g.name + ' has died.');
                    player.guards.splice(gi, 1);
                    continue;
                }
                // Guard follows player
                npc.townId = player.townId;
            }
        }
        player.personalGuards = player.guards.length;
        if (player.guards.length === 0) return;

        var wage = (CONFIG.PLAYER_GUARD_DAILY_WAGE || 6) * player.guards.length;
        player.gold -= wage;
        logFinance(-wage, 'guards', 'Guard wages (' + player.guards.length + ')');
        if (player.gold < 0) {
            while (player.gold < 0 && player.guards.length > 0) {
                var dismissed = player.guards.pop();
                player.gold += (CONFIG.PLAYER_GUARD_DAILY_WAGE || 6);
                // Return NPC to current town
                if (dismissed.personId && Engine.getPerson) {
                    var dnpc = Engine.getPerson(dismissed.personId);
                    if (dnpc && dnpc.alive) {
                        dnpc.isPlayerGuard = false;
                        dnpc.occupation = dnpc.previousOccupation || 'unemployed';
                        dnpc.townId = player.townId || dnpc.previousTownId || dnpc.townId;
                        delete dnpc.previousOccupation;
                        delete dnpc.previousTownId;
                    }
                }
                Engine.logEvent('\uD83D\uDCB8 ' + dismissed.name + ' leaves \u2014 you can\'t afford the wages. (' + player.guards.length + ' remaining)');
            }
            if (player.gold < 0) player.gold = 0;
        }
        player.personalGuards = player.guards.length;
    }

    function getEncounterChance() {
        var rng = Engine.getRng();
        if (!rng) return { chance: 0, riskLevel: 'none', isWartime: false, isSea: false };

        var isSea = !!player.travelBySea;
        var isWartime = isInWarzone();
        var chance;

        if (isSea) {
            // Sea: ship defense is main factor
            chance = CONFIG.ENCOUNTER_SEA_BASE_CHANCE || 0.04;
            var ship = getBestShip();
            if (ship) {
                var def = getShipDefense(ship);
                var factor = CONFIG.ENCOUNTER_SEA_SHIP_DEFENSE_FACTOR || 0.06;
                chance *= Math.max(0.05, 1.0 - def * factor);
            }
            // Guards moderate help at sea
            var guards = (player.guards || []).length;            for (var g = 0; g < guards; g++) {
                chance *= (CONFIG.ENCOUNTER_SEA_GUARD_REDUCTION || 0.70);
            }
            if (hasSkill('veteran_guards') && guards > 0) chance *= 0.70;
            // Weapons/armor tiny help at sea
            if (player.weapon) chance *= (CONFIG.ENCOUNTER_SEA_WEAPON_REDUCTION || 0.97);
            if (player.armor) chance *= (CONFIG.ENCOUNTER_SEA_ARMOR_REDUCTION || 0.98);
            // Skills
            if (hasSkill('street_smart')) chance *= (CONFIG.ENCOUNTER_SKILL_STREET_SMART || 0.90);
            if (hasSkill('intimidating_presence')) chance *= (CONFIG.ENCOUNTER_SKILL_INTIMIDATING || 0.85);
            if (hasSkill('expert_navigator')) chance *= 0.90;
            // Bandit evasion skills (sea pirates too)
            if (!isWartime) {
                if (hasSkill('bandit_mastery')) chance *= 0.50;
                else if (hasSkill('bandit_evasion')) chance *= 0.75;
            } else {
                if (hasSkill('bandit_mastery')) chance *= 0.75;
            }
            // Pirate events
            var w = Engine.getWorld();
            if (w) {
                for (var ei = 0; ei < w.events.length; ei++) {
                    if (w.events[ei].active && w.events[ei].type === 'pirates') chance *= (w.events[ei].seaRiskMultiplier || 3);
                }
            }
            // Clamp
            chance = Math.max(CONFIG.ENCOUNTER_SEA_MIN_CHANCE || 0.0001, Math.min(CONFIG.ENCOUNTER_SEA_MAX_CHANCE || 0.10, chance));
        } else {
            // Land encounters
            chance = CONFIG.ENCOUNTER_LAND_BASE_CHANCE || 0.05;
            // Road danger
            if (player.travelRoute && player.travelRoute.length > 0) {
                var currentSegIdx = Math.min(Math.floor(player.travelProgress * player.travelRoute.length), player.travelRoute.length - 1);
                var seg = player.travelRoute[currentSegIdx];
                if (seg) {
                    if (seg.safe === false || (seg.banditThreat || 0) > 50) {
                        chance *= (CONFIG.ENCOUNTER_ROAD_DANGER_MULT || 1.5);
                    }
                    // Check connected town security
                    var destTown = Engine.findTown(seg.toTownId);
                    var fromTown = Engine.findTown(seg.fromTownId);
                    if (destTown && (destTown.security || 50) < 30) chance *= (CONFIG.ENCOUNTER_POOR_SECURITY_MULT || 1.3);
                    if (fromTown && (fromTown.security || 50) < 30) chance *= (CONFIG.ENCOUNTER_POOR_SECURITY_MULT || 1.3);
                }
            }
            // Guards
            var guards2 = player.personalGuards || 0;
            for (var g2 = 0; g2 < guards2; g2++) {
                chance *= (1.0 - (CONFIG.ENCOUNTER_GUARD_REDUCTION || 0.40));
            }
            if (hasSkill('veteran_guards') && guards2 > 0) chance *= 0.70;
            // Horse
            if (player.horses && player.horses.length > 0) chance *= (CONFIG.ENCOUNTER_HORSE_REDUCTION || 0.85);
            // Paid transit
            if (player.travelPaid) chance *= (CONFIG.ENCOUNTER_PAID_TRANSIT_REDUCTION || 0.25);
            // Weapons/armor
            if (player.weapon) chance *= (CONFIG.ENCOUNTER_WEAPON_REDUCTION || 0.90);
            if (player.armor) chance *= (CONFIG.ENCOUNTER_ARMOR_REDUCTION || 0.93);
            // Skills
            if (hasSkill('street_smart')) chance *= (CONFIG.ENCOUNTER_SKILL_STREET_SMART || 0.90);
            if (hasSkill('intimidating_presence')) chance *= (CONFIG.ENCOUNTER_SKILL_INTIMIDATING || 0.85);
            if (hasSkill('road_knowledge')) chance *= 0.92;
            // Bandit evasion skills
            if (!isWartime) {
                if (hasSkill('bandit_mastery')) chance *= 0.50;
                else if (hasSkill('bandit_evasion')) chance *= 0.75;
            } else {
                if (hasSkill('bandit_mastery')) chance *= 0.75;
            }
            // Clamp
            chance = Math.max(CONFIG.ENCOUNTER_LAND_MIN_CHANCE || 0.001, Math.min(CONFIG.ENCOUNTER_LAND_MAX_CHANCE || 0.15, chance));
        }

        // Wartime multiplier
        if (isWartime) {
            chance *= (CONFIG.ENCOUNTER_WARTIME_CHANCE_MULT || 1.8);
            // Re-clamp after wartime mult
            var maxChance = isSea ? (CONFIG.ENCOUNTER_SEA_MAX_CHANCE || 0.10) : (CONFIG.ENCOUNTER_LAND_MAX_CHANCE || 0.15);
            chance = Math.min(maxChance, chance);
        }

        // Determine risk level
        var riskLevel = 'low';
        if (chance >= 0.06) riskLevel = 'high';
        else if (chance >= 0.025) riskLevel = 'medium';

        return { chance: chance, riskLevel: riskLevel, isWartime: isWartime, isSea: isSea };
    }

    function isInWarzone() {
        if (!player.travelRoute || player.travelRoute.length === 0) return false;
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        if (!activeWars || Object.keys(activeWars).length === 0) return false;
        for (var i = 0; i < player.travelRoute.length; i++) {
            var seg = player.travelRoute[i];
            var fromTown = Engine.findTown(seg.fromTownId);
            var toTown = Engine.findTown(seg.toTownId);
            if (!fromTown || !toTown) continue;
            for (var warId in activeWars) {
                var war = activeWars[warId];
                if (!war) continue;
                var sides = war.sides || [war.attackerId, war.defenderId];
                if (sides.length < 2) continue;
                var fromSide = sides.indexOf(fromTown.kingdomId);
                var toSide = sides.indexOf(toTown.kingdomId);
                if (fromSide >= 0 && toSide >= 0 && fromSide !== toSide) return true;
            }
        }
        return false;
    }

    function checkDailyEncounter() {
        if (!player.traveling) return;
        if (player.encounterPending) return; // already awaiting resolution
        var rng = Engine.getRng();
        if (!rng) return;

        var info = getEncounterChance();
        if (info.chance <= 0) return;

        if (!rng.chance(info.chance)) return;

        // Encounter triggered! Pause game and show choice dialog
        var isSea = info.isSea;
        var isWartime = info.isWartime;

        // Determine bandit strength (RNG element)
        var banditStrength = (CONFIG.ENCOUNTER_FIGHT_BANDIT_STRENGTH_MIN || 0.10) +
            rng.random() * ((CONFIG.ENCOUNTER_FIGHT_BANDIT_STRENGTH_MAX || 0.30) - (CONFIG.ENCOUNTER_FIGHT_BANDIT_STRENGTH_MIN || 0.10));
        if (isWartime) banditStrength *= (CONFIG.ENCOUNTER_WARTIME_FIGHT_DIFFICULTY || 1.4);

        // Calculate fight win chance
        var fightWin = calculateFightWinChance(isSea, isWartime, banditStrength);

        // Calculate negotiate success chance
        var negotiateChance = CONFIG.ENCOUNTER_NEGOTIATE_BASE_SUCCESS || 0.40;
        if (hasSkill('silver_tongue') || (player.heirTraits && player.heirTraits.indexOf('silver_tongue') >= 0)) negotiateChance += (CONFIG.ENCOUNTER_NEGOTIATE_SKILL_BONUS || 0.15);
        if (hasSkill('escape_artist')) negotiateChance += 0.10;
        if (hasSkill('street_smart')) negotiateChance += 0.10;
        negotiateChance = Math.min(0.90, Math.max(0.10, negotiateChance));

        player.encounterPending = {
            isSea: isSea,
            isWartime: isWartime,
            banditStrength: banditStrength,
            fightWinChance: fightWin,
            negotiateChance: negotiateChance,
            day: Engine.getDay()
        };

        // Pause the game so player can make their choice
        if (typeof Engine.pause === 'function') Engine.pause();

        // Trigger the UI dialog
        if (typeof window._showEncounterDialog === 'function') {
            window._showEncounterDialog(player.encounterPending);
        }
    }

    function calculateFightWinChance(isSea, isWartime, banditStrength) {
        var win = CONFIG.ENCOUNTER_FIGHT_BASE_WIN || 0.35;

        // Guards
        var guards = (player.guards || []).length;
        if (isSea) {
            win += guards * (CONFIG.ENCOUNTER_SEA_FIGHT_GUARD_BONUS || 0.08);
        } else {
            win += guards * (CONFIG.ENCOUNTER_FIGHT_GUARD_BONUS || 0.12);
        }
        if (hasSkill('veteran_guards') && guards > 0) win += 0.10;

        // Weapons
        if (player.weapon) {
            var wBonus = isSea ? (CONFIG.ENCOUNTER_SEA_FIGHT_WEAPON_BONUS || 0.02) : (CONFIG.ENCOUNTER_FIGHT_WEAPON_BONUS || 0.10);
            if (typeof player.weapon === 'object') {
                win += wBonus * (player.weapon.combatBonus || 0.2) / 0.2;
            } else {
                win += wBonus;
            }
        }

        // Armor
        if (player.armor) {
            var aBonus = CONFIG.ENCOUNTER_FIGHT_ARMOR_BONUS || 0.05;
            if (typeof player.armor === 'object') {
                win += aBonus * (player.armor.combatBonus || 0.3) / 0.3;
            } else {
                win += aBonus;
            }
        }

        // Ship defense (sea only)
        if (isSea) {
            var ship = getBestShip();
            if (ship) {
                var def = getShipDefense(ship);
                win += def * (CONFIG.ENCOUNTER_SEA_FIGHT_SHIP_DEFENSE_BONUS || 0.02);
                win += (ship.cannons || 0) * (CONFIG.ENCOUNTER_SEA_FIGHT_CANNON_BONUS || 0.06);
            }
        }

        // Skills
        if (hasSkill('battle_hardened')) {
            win += (CONFIG.ENCOUNTER_FIGHT_SKILL_BATTLE_HARDENED || 0.20);
        } else if (hasSkill('combat_trained')) {
            win += (CONFIG.ENCOUNTER_FIGHT_SKILL_COMBAT_TRAINED || 0.10);
        }
        if (hasSkill('combat_proficiency')) win += (CONFIG.ENCOUNTER_FIGHT_SKILL_COMBAT_PROFICIENCY || 0.10);

        // Low needs penalty
        var penalty = CONFIG.ENCOUNTER_FIGHT_LOW_NEEDS_PENALTY || 0.08;
        if ((player.hunger || 100) < 20) win -= penalty;
        if ((player.thirst || 100) < 20) win -= penalty;
        if ((player.energy || 100) < 20) win -= penalty;

        // Bandit strength (RNG difficulty)
        win -= banditStrength;

        // Clamp
        win = Math.max(CONFIG.ENCOUNTER_FIGHT_MIN_WIN || 0.05, Math.min(CONFIG.ENCOUNTER_FIGHT_MAX_WIN || 0.95, win));
        return win;
    }

    function resolveEncounter(choice) {
        var enc = player.encounterPending;
        if (!enc) return { success: false, message: 'No encounter pending.' };

        var rng = Engine.getRng();
        if (!rng) rng = { random: Math.random, chance: function(c) { return Math.random() < c; } };

        var result = { choice: choice, success: false, goldLost: 0, goodsLost: {}, injured: false, injurySeverity: null, shipDamaged: false, died: false };
        var isSea = enc.isSea;
        var isWartime = enc.isWartime;
        var enemyName = isWartime ? (isSea ? 'enemy navy' : 'enemy soldiers') : (isSea ? 'pirates' : 'bandits');

        if (choice === 'surrender') {
            // Surrender: lose all goods + 50% gold capped at 500g
            var goldPct = CONFIG.ENCOUNTER_SURRENDER_GOLD_PCT || 0.50;
            var goldCap = CONFIG.ENCOUNTER_SURRENDER_GOLD_CAP || 500;
            var goldLost = Math.min(Math.floor(player.gold * goldPct), goldCap);
            player.gold -= goldLost;
            result.goldLost = goldLost;
            logFinance(-goldLost, 'encounter', 'Surrendered to ' + enemyName);

            // Lose all inventory
            for (var key in player.inventory) {
                if (player.inventory[key] > 0) {
                    result.goodsLost[key] = player.inventory[key];
                    player.inventory[key] = 0;
                }
            }

            result.success = true;
            var emoji = isWartime ? '🏳️' : '💰';
            Engine.logEvent(emoji + ' You surrendered to ' + enemyName + '. Lost ' + goldLost + 'g and all goods.');
            autoJournalCapture('encounter', 'Surrendered to ' + enemyName + ' on the ' + (isSea ? 'seas' : 'road') + '. They took everything.', { mood: 'defeated' });

        } else if (choice === 'negotiate') {
            var negSuccess = rng.chance(enc.negotiateChance);

            if (negSuccess) {
                // Successful negotiation: lose 50% of goods (random) + 10% gold (cap 250g)
                var goldPct2 = CONFIG.ENCOUNTER_NEGOTIATE_GOLD_PCT || 0.10;
                var goldCap2 = CONFIG.ENCOUNTER_NEGOTIATE_GOLD_CAP || 250;
                var goldLost2 = Math.min(Math.floor(player.gold * goldPct2), goldCap2);
                player.gold -= goldLost2;
                result.goldLost = goldLost2;
                logFinance(-goldLost2, 'encounter', 'Negotiated with ' + enemyName);

                var goodsPct = CONFIG.ENCOUNTER_NEGOTIATE_GOODS_PCT || 0.50;
                var invKeys = Object.keys(player.inventory).filter(function(k) { return player.inventory[k] > 0; });
                // Randomly select half the inventory types to lose
                var shuffled = rng.shuffle ? rng.shuffle(invKeys.slice()) : invKeys.sort(function() { return rng.random() - 0.5; });
                var typesToLose = Math.ceil(shuffled.length * goodsPct);
                for (var ni = 0; ni < typesToLose; ni++) {
                    var nkey = shuffled[ni];
                    var loseQty = player.inventory[nkey];
                    result.goodsLost[nkey] = loseQty;
                    player.inventory[nkey] = 0;
                }

                result.success = true;
                Engine.logEvent('🤝 You negotiated with the ' + enemyName + '. Lost ' + goldLost2 + 'g and some goods, but kept the rest.');
                autoJournalCapture('encounter', 'Managed to talk my way through a ' + enemyName + ' encounter. Lost some goods but kept my life.', { mood: 'relieved' });
            } else {
                // Failed negotiation — becomes a fight (with penalty)
                var fightWin = Math.max(CONFIG.ENCOUNTER_FIGHT_MIN_WIN || 0.05, enc.fightWinChance - 0.10);
                result = resolveFight(rng, fightWin, isSea, isWartime, enemyName);
                result.choice = 'negotiate_failed';
                Engine.logEvent('❌ Negotiation failed! The ' + enemyName + ' attacked!');
            }

        } else if (choice === 'fight') {
            result = resolveFight(rng, enc.fightWinChance, isSea, isWartime, enemyName);
            result.choice = 'fight';
        }

        player.encounterPending = null;
        // Resume game
        if (typeof Engine.unpause === 'function') Engine.unpause();
        return result;
    }

    function resolveFight(rng, winChance, isSea, isWartime, enemyName) {
        var result = { success: false, goldLost: 0, goodsLost: {}, injured: false, injurySeverity: null, shipDamaged: false, died: false };

        // Escape Artist: variable flee chance (5-30%) based on circumstances
        if (hasSkill('escape_artist')) {
            var fleeChance = 0.15; // base 15%
            // Horse gives big bonus on land
            if (!isSea && player.horses && player.horses.length > 0) fleeChance += 0.08;
            // High energy helps
            if ((player.energy || 100) >= 70) fleeChance += 0.05;
            else if ((player.energy || 100) < 30) fleeChance -= 0.05;
            // Good hunger/thirst helps
            if ((player.hunger || 100) >= 50 && (player.thirst || 100) >= 50) fleeChance += 0.03;
            else if ((player.hunger || 100) < 20 || (player.thirst || 100) < 20) fleeChance -= 0.03;
            // Sea is harder to flee on
            if (isSea) fleeChance -= 0.05;
            // Wartime soldiers are more organized
            if (isWartime) fleeChance -= 0.04;
            // Light armor bonus (no armor = nimble)
            if (!player.armor) fleeChance += 0.02;
            // Street smart helps
            if (hasSkill('street_smart')) fleeChance += 0.03;
            fleeChance = Math.max(0.05, Math.min(0.30, fleeChance));
            if (rng.chance(fleeChance)) {
                result.success = true;
                result.fled = true;
                Engine.logEvent('🏃 You used your wits to escape the ' + enemyName + ' without a fight!');
                autoJournalCapture('encounter', 'Managed to slip away from ' + enemyName + ' before the fighting started.', { mood: 'relieved' });
                return result;
            }
            // Flee failed — must fight
            Engine.logEvent('🏃 You tried to escape but the ' + enemyName + ' cut off your retreat!');
        }

        var won = rng.chance(winChance);

        // God mode invincibility
        if (window._godInvincible) won = true;

        if (won) {
            // Won the fight!
            result.success = true;
            Engine.logEvent('⚔️ You fought off the ' + enemyName + '!');
            grantXP(15); // combat XP

            // Sea: ship may take damage even on win
            if (isSea) {
                var dmgChance = CONFIG.ENCOUNTER_FIGHT_WIN_SHIP_DAMAGE_CHANCE || 0.40;
                if (rng.chance(dmgChance)) {
                    var ship = getBestShip();
                    if (ship) {
                        var dmg = 5 + Math.floor(rng.random() * 15);
                        ship.hullHealth = Math.max(0, (ship.hullHealth || 100) - dmg);
                        result.shipDamaged = true;
                        Engine.logEvent('🔨 Your ship took ' + dmg + ' hull damage in the fight.');
                    }
                }
            }

            autoJournalCapture('encounter', 'Fought off ' + enemyName + ' on the ' + (isSea ? 'seas' : 'road') + '. Victory!', { mood: 'proud' });
        } else {
            // Lost the fight
            result.success = false;

            if (isSea) {
                // Sea loss: wash up at destination with severe illness, lose all goods
                for (var key in player.inventory) {
                    if (player.inventory[key] > 0) {
                        result.goodsLost[key] = player.inventory[key];
                        player.inventory[key] = 0;
                    }
                }
                // Severe illness from washing ashore
                player.illnesses = player.illnesses || [];
                var seaIllness = { name: 'Waterlogged Fever', type: 'waterlogged_fever', severity: 'severe', dayOccurred: Engine.getDay(), treated: false, contagious: false, daysRemaining: 30 + Math.floor(rng.random() * 20) };
                player.illnesses.push(seaIllness);
                result.injured = true;
                result.injurySeverity = 'severe';
                // Ship may be damaged or destroyed
                var ship2 = getBestShip();
                if (ship2) {
                    var heavyDmg = 30 + Math.floor(rng.random() * 40);
                    ship2.hullHealth = Math.max(0, (ship2.hullHealth || 100) - heavyDmg);
                    result.shipDamaged = true;
                    if (ship2.hullHealth <= 0) {
                        Engine.logEvent('💀 Your ' + ship2.name + ' was destroyed by ' + enemyName + '!');
                        player.ships = player.ships.filter(function(s) { return s.id !== ship2.id; });
                    }
                }
                Engine.logEvent('💀 You lost the fight against ' + enemyName + '! You washed ashore ill and with nothing.');
                autoJournalCapture('encounter', 'Defeated by ' + enemyName + ' at sea. Washed ashore half-drowned with a terrible fever.', { mood: 'desperate' });
            } else {
                // Land loss: moderate or severe injury + lose all goods
                for (var key2 in player.inventory) {
                    if (player.inventory[key2] > 0) {
                        result.goodsLost[key2] = player.inventory[key2];
                        player.inventory[key2] = 0;
                    }
                }

                // Injury: moderate or severe
                var injuryMult = isWartime ? (CONFIG.ENCOUNTER_WARTIME_INJURY_MULT || 1.5) : 1.0;
                var severeChance = (CONFIG.ENCOUNTER_FIGHT_LOSS_INJURY_MODERATE_CHANCE || 0.50);
                // Armor reduces severe chance
                if (player.armor) {
                    var armorReduction = (typeof player.armor === 'object') ? (player.armor.combatBonus || 0.3) : 0.3;
                    severeChance *= (1.0 - armorReduction * 0.5);
                }
                if (isWartime) severeChance *= injuryMult;
                severeChance = Math.min(0.90, severeChance);

                var severity = rng.chance(severeChance) ? 'severe' : 'moderate';
                player.injuries = player.injuries || [];
                var injuryNames = isWartime
                    ? ['Sword Wound', 'Arrow Wound', 'Battle Trauma', 'Spear Wound', 'Shield Bash Concussion']
                    : ['Knife Wound', 'Blunt Trauma', 'Bandit Beating', 'Club Injury', 'Road Ambush Wound'];
                var injName = rng.pick ? rng.pick(injuryNames) : injuryNames[Math.floor(rng.random() * injuryNames.length)];
                player.injuries.push({ name: injName, type: 'encounter_wound', severity: severity, dayOccurred: Engine.getDay(), treated: false });
                result.injured = true;
                result.injurySeverity = severity;

                // Small gold loss too
                var goldLost3 = Math.min(Math.floor(player.gold * 0.20), 200);
                player.gold -= goldLost3;
                result.goldLost = goldLost3;
                logFinance(-goldLost3, 'encounter', 'Robbed by ' + enemyName);

                // Death check (very small chance, higher in wartime)
                var deathChance = isWartime ? 0.05 : 0.02;
                if (player.armor) deathChance *= 0.5;
                if (hasSkill('battle_hardened')) deathChance *= 0.3;
                if (window._godInvincible) deathChance = 0;
                if (rng.chance(deathChance)) {
                    result.died = true;
                    player.alive = false;
                    Engine.logEvent('💀 ' + player.fullName + ' was killed by ' + enemyName + '!');
                } else {
                    Engine.logEvent('⚔️ You lost the fight against ' + enemyName + '! Suffered a ' + severity + ' ' + injName + ' and lost all your goods.');
                }

                autoJournalCapture('encounter', 'Defeated by ' + enemyName + '. Suffered a ' + severity + ' injury. Lost everything I was carrying.', { mood: 'defeated' });
            }
        }

        // Guard casualties — same death/injury chance as player
        player.guards = player.guards || [];
        if (player.guards.length > 0) {
            result.guardCasualties = [];
            var deathChanceGuard = isWartime ? 0.05 : 0.02;
            var injuryChanceGuard = won ? 0.15 : 0.50;
            if (isSea && !won) injuryChanceGuard = 0.60;
            for (var _gi = player.guards.length - 1; _gi >= 0; _gi--) {
                var _guard = player.guards[_gi];
                var guardNpc = (_guard.personId && Engine.getPerson) ? Engine.getPerson(_guard.personId) : null;
                if (!won && rng.chance(deathChanceGuard)) {
                    // Guard killed
                    if (guardNpc) { guardNpc.alive = false; guardNpc.deathDay = Engine.getDay(); guardNpc.deathCause = 'combat'; guardNpc.isPlayerGuard = false; }
                    result.guardCasualties.push({ name: _guard.name, outcome: 'killed' });
                    Engine.logEvent('💀 Your guard ' + _guard.name + ' was killed by ' + enemyName + '!');
                    player.guards.splice(_gi, 1);
                } else if (rng.chance(injuryChanceGuard)) {
                    // Guard injured
                    var gSeverity = rng.chance(0.4) ? 'severe' : 'moderate';
                    if (guardNpc) { guardNpc.injured = true; guardNpc.injurySeverity = gSeverity; }
                    result.guardCasualties.push({ name: _guard.name, outcome: 'injured', severity: gSeverity });
                    Engine.logEvent('🩹 Your guard ' + _guard.name + ' suffered a ' + gSeverity + ' injury in the fight.');
                }
            }
            player.personalGuards = player.guards.length;
        }

        return result;
    }

    function getEncounterRiskLabel() {
        if (!player.traveling) return null;
        var info = getEncounterChance();
        if (info.chance <= 0) return null;
        var label, color, icon;
        if (info.riskLevel === 'high') {
            label = 'High'; color = '#e74c3c'; icon = '🔴';
        } else if (info.riskLevel === 'medium') {
            label = 'Medium'; color = '#f39c12'; icon = '🟡';
        } else {
            label = 'Low'; color = '#2ecc71'; icon = '🟢';
        }
        var typeLabel = info.isSea ? (info.isWartime ? 'Navy' : 'Pirate') : (info.isWartime ? 'Ambush' : 'Bandit');
        return { label: label, color: color, icon: icon, typeLabel: typeLabel, chance: info.chance };
    }

    function checkWartimeAmbush(route) {
        if (!route || route.length === 0) return null;
        var rng = Engine.getRng();
        if (!rng) return null;

        // Check if any route segment is in a warzone
        var inWarzone = false;
        var activeWars = Engine.getActiveWars ? Engine.getActiveWars() : {};
        if (!activeWars || Object.keys(activeWars).length === 0) return null;

        for (var i = 0; i < route.length; i++) {
            var seg = route[i];
            var fromTown = Engine.findTown(seg.fromTownId);
            var toTown = Engine.findTown(seg.toTownId);
            if (!fromTown || !toTown) continue;
            // Check if these towns belong to warring kingdoms
            for (var warId in activeWars) {
                var war = activeWars[warId];
                if (!war) continue;
                var sides = war.sides || [war.attackerId, war.defenderId];
                if (sides.length < 2) continue;
                var fromSide = sides.indexOf(fromTown.kingdomId);
                var toSide = sides.indexOf(toTown.kingdomId);
                if (fromSide >= 0 && toSide >= 0 && fromSide !== toSide) { inWarzone = true; break; }
                // Check if near frontline
                if (fromSide >= 0 || toSide >= 0) {
                    var frontlineTowns = getFrontlineTowns(sides);
                    if (frontlineTowns.has(fromTown.id) || frontlineTowns.has(toTown.id)) { inWarzone = true; break; }
                }
            }
            if (inWarzone) break;
        }

        if (!inWarzone) return null;

        var chance = CONFIG.WARTIME_AMBUSH_BASE_CHANCE;

        // Military goods bonus
        var milGoods = ['swords', 'armor', 'bows', 'arrows', 'horses'];
        var carryingMilitary = milGoods.some(g => (player.inventory[g] || 0) > 0);
        if (carryingMilitary) chance += CONFIG.WARTIME_AMBUSH_MILITARY_GOODS_BONUS;

        // Enemy citizen bonus
        for (var wid in activeWars) {
            var w = activeWars[wid];
            var wSides = w.sides || [w.attackerId, w.defenderId];
            for (var s = 0; s < wSides.length; s++) {
                if (wSides[s] !== player.citizenshipKingdomId) {
                    var enemySide = wSides[s];
                    var routeTowns = route.map(r => Engine.findTown(r.toTownId)).filter(Boolean);
                    if (routeTowns.some(t => t.kingdomId === enemySide)) {
                        chance += CONFIG.WARTIME_AMBUSH_ENEMY_CITIZEN_BONUS;
                        break;
                    }
                }
            }
        }

        // Mitigations
        if (player.armedEscort && player.armedEscort.active) chance -= CONFIG.WARTIME_ESCORT_REDUCTION;
        if (hasSkill('combat_trained')) chance -= 0.10;
        if (hasSkill('battle_hardened')) chance -= 0.15;
        if (hasSkill('fortified_caravans')) chance -= 0.10;
        if (player.weapon) chance -= (typeof player.weapon === 'object') ? (player.weapon.combatBonus * 0.25) : 0.05;
        if (player.armor) chance -= (typeof player.armor === 'object') ? (player.armor.combatBonus * 0.17) : 0.05;
        var rankIdx = getPlayerRankIndex();
        if (rankIdx >= 4) chance -= 0.05; // Minor Noble+

        chance = Math.max(0.02, chance);

        if (!rng.chance(chance)) return null;

        // Ambushed!
        var inventoryLoss = {};
        var invKeys = Object.keys(player.inventory).filter(k => player.inventory[k] > 0);
        var lossPct = 0.2 + rng.random() * 0.3; // 20-50%
        for (var k = 0; k < invKeys.length; k++) {
            var key = invKeys[k];
            var loseQty = Math.floor(player.inventory[key] * lossPct);
            if (loseQty > 0) {
                player.inventory[key] -= loseQty;
                if (player.inventory[key] <= 0) delete player.inventory[key];
                inventoryLoss[key] = loseQty;
            }
        }

        var goldLossPct = 0.1 + rng.random() * 0.2; // 10-30%
        var goldLost = Math.floor(player.gold * goldLossPct);
        player.gold -= goldLost;

        var injured = rng.chance(0.15);
        if (injured) {
            player.injuries = player.injuries || [];
            player.injuries.push({ type: 'ambush_wound', severity: 'moderate', dayOccurred: Engine.getDay(), treated: false });
        }

        var deathChance = 0.03;
        if (player.weapon) deathChance -= (typeof player.weapon === 'object') ? (player.weapon.combatBonus * 0.05) : 0.01;
        if (player.armor) deathChance -= (typeof player.armor === 'object') ? (player.armor.combatBonus * 0.05) : 0.01;
        if (hasSkill('combat_trained')) deathChance -= 0.005;
        var died = rng.chance(Math.max(0.001, deathChance));

        Engine.logEvent('⚔️ ' + player.fullName + ' was ambushed by enemy soldiers! Lost ' + goldLost + 'g and ' + Object.keys(inventoryLoss).length + ' types of goods.' + (injured ? ' Suffered injuries.' : '') + (died ? ' KILLED IN AMBUSH!' : ''));

        return { ambushed: true, goldLost: goldLost, inventoryLoss: inventoryLoss, injured: injured, died: died };
    }

    function getFrontlineTowns(sides) {
        var frontline = new Set();
        if (!sides || sides.length < 2) return frontline;
        var allTowns = Engine.getTowns ? Engine.getTowns() : [];
        var side0Towns = allTowns.filter(t => t.kingdomId === sides[0]);
        var side1Towns = allTowns.filter(t => t.kingdomId === sides[1]);
        for (var i = 0; i < side0Towns.length; i++) {
            for (var j = 0; j < side1Towns.length; j++) {
                var dist = Math.hypot((side0Towns[i].x || 0) - (side1Towns[j].x || 0), (side0Towns[i].y || 0) - (side1Towns[j].y || 0));
                if (dist < CONFIG.WARTIME_FRONTLINE_DISTANCE) {
                    frontline.add(side0Towns[i].id);
                    frontline.add(side1Towns[j].id);
                }
            }
        }
        return frontline;
    }

    // ========================================================
    // §12L  ORDER PERMIT BONUSES
    // ========================================================
    function getOrderCompletionBonus(order) {
        if (!order) return 0;
        var totalValue = (order.qty || 0) * (order.assignedPrice || order.maxPricePerUnit || 0);
        var bonusPct = 0.10 + Math.random() * 0.10; // 10-20%
        return Math.floor(totalValue * bonusPct);
    }

    function canBidOnBannedOrder(kingdomId, resourceId) {
        var permits = player.productionPermits || {};
        var kingdomPermits = permits[kingdomId] || [];
        return kingdomPermits.includes(resourceId);
    }

    // ========================================================
    // §12B  GAME START SCENARIOS & FAMILY SYSTEM
    // ========================================================

    function applyGameStart(startConfig) {
        const rng = Engine.getRng();
        player.gameStart = startConfig.id;

        // Apply starting gold
        player.gold = startConfig.startGold;

        // Apply starting rank
        if (player.citizenshipKingdomId) {
            player.socialRank[player.citizenshipKingdomId] = startConfig.startRank || 0;
        }

        // Apply citizenship
        if (!startConfig.startCitizen) {
            player.citizenshipKingdomId = null;
            player.socialRank = {};
        }

        // Generate family if applicable
        if (startConfig.hasFamily) {
            generatePlayerFamily(startConfig);
        }

        // Apply starting house
        if (startConfig.startHouse) {
            const house = {
                id: houseUid(),
                type: startConfig.startHouse,
                townId: player.townId,
                purchaseDay: 0,
                occupants: [],
                homeStorage: {},
                isRental: false,
                rentAccumulated: 0,
                purchaseCost: 0,
                condition: 'used', // starting house is not brand new
                builtDay: 0,
                lastRepairDay: 0
            };
            if (!player.houses) player.houses = [];
            player.houses.push(house);
            if (!player.primaryHouseId) player.primaryHouseId = house.id;

            // Grant a land plot for the starting house (houses require land except apartments/portable)
            var startHt = CONFIG.HOUSING_TYPES.find(function(h) { return h.id === startConfig.startHouse; });
            if (startHt && startHt.id !== 'apartment' && !startHt.portable) {
                player.landOwned = player.landOwned || {};
                var startLandSlots = startHt.landSlots || 1;
                player.landOwned[player.townId] = (player.landOwned[player.townId] || 0) + startLandSlots;
            }
        }

        // Apply starting buildings
        var numBuildings = startConfig.startBuildings || (startConfig.startBuilding ? 1 : 0);
        if (numBuildings > 0) {
            // Grant land plots for starting buildings (1 per building unless landSlots specified)
            player.landOwned = player.landOwned || {};
            player.landOwned[player.townId] = (player.landOwned[player.townId] || 0) + numBuildings;

            var basicBuildings = ['bakery', 'brewery', 'workshop', 'flour_mill', 'wheat_farm'];
            for (var bi = 0; bi < numBuildings; bi++) {
                var bType = basicBuildings[bi % basicBuildings.length];
                var bt = Engine.findBuildingType(bType);
                if (bt) {
                    var bld = {
                        id: buildingUid(),
                        type: bType,
                        townId: player.townId,
                        workers: [],
                        active: true,
                        level: 1,
                        builtDay: 0,
                        condition: 'new',
                        lastRepairDay: 0,
                        transferTarget: null,
                        transferEnabled: false
                    };
                    player.buildings.push(bld);
                    var town = Engine.findTown(player.townId);
                    if (town) {
                        town.buildings.push({ type: bType, level: 1, ownerId: 'player', builtDay: 0, condition: 'new', lastRepairDay: 0 });
                    }
                }
            }
        }

        // Apply starting workers
        if (startConfig.startWorkers) {
            var townPeople = Engine.getPeople(player.townId);
            var hirable = townPeople.filter(function(p) {
                return p.alive && !p.employerId && p.occupation !== 'noble' && p.occupation !== 'soldier' && p.age >= 18;
            });
            for (var wi = 0; wi < Math.min(startConfig.startWorkers, hirable.length); wi++) {
                var w = hirable[wi];
                w.employerId = 'player';
                player.employees.push(w.id);
            }
        }

        // Noble Birth: extra reputation
        if (startConfig.id === 'very_easy' && player.startingKingdomId) {
            player.reputation[player.startingKingdomId] = 80;
        }

        // Special starts
        if (startConfig.special === 'indentured') {
            initIndenturedStart();
        } else if (startConfig.special === 'pilgrim') {
            initPilgrimStart();
        } else if (startConfig.special === 'shipwrecked') {
            initShipwreckedStart();
        } else if (startConfig.special === 'musician') {
            initMusicianStart();
        } else if (startConfig.special === 'military_leader') {
            initMilitaryLeaderStart();
        } else if (startConfig.special === 'scholar') {
            initScholarStart();
        }

        Engine.logEvent(player.fullName + ' begins their journey as ' + (startConfig.name || 'an adventurer') + '.');
    }

    // ── Family Generation ──
    function generatePlayerFamily(startConfig) {
        var rng = Engine.getRng();
        var town = Engine.findTown(player.townId);
        if (!town) return;

        var townPeople = Engine.getPeople(player.townId);
        player.familyMembers = [];

        // Determine family wealth class
        var familyGold = 100;
        if (startConfig.id === 'easy') familyGold = rng.randInt(500, 1000);
        else if (startConfig.id === 'very_easy') familyGold = rng.randInt(2000, 5000);
        else familyGold = rng.randInt(50, 200);

        // Find suitable NPCs for parents (ages 40-55, same town)
        var potentialParents = townPeople.filter(function(p) {
            return p.alive && p.age >= 40 && p.age <= 55 && !p.employerId && !p.isPlayerFamily;
        });

        var parentCount = 0;
        var roles = ['father', 'mother'];
        var parentSexes = ['M', 'F'];
        for (var pi = 0; pi < 2 && pi < potentialParents.length; pi++) {
            // Find matching sex
            var parent = null;
            for (var pj = 0; pj < potentialParents.length; pj++) {
                if (potentialParents[pj].sex === parentSexes[pi] && !potentialParents[pj]._familyUsed) {
                    parent = potentialParents[pj];
                    parent._familyUsed = true;
                    break;
                }
            }
            if (!parent) {
                // Take any available
                for (var pk = 0; pk < potentialParents.length; pk++) {
                    if (!potentialParents[pk]._familyUsed) {
                        parent = potentialParents[pk];
                        parent._familyUsed = true;
                        break;
                    }
                }
            }
            if (!parent) break;

            parent.isPlayerFamily = true;
            parent.familyRole = 'parent';
            parent.gold = Math.floor(familyGold / 2);
            if (startConfig.id === 'easy') parent.occupation = 'merchant';
            if (startConfig.id === 'very_easy') parent.wealthClass = 'upper';

            var relLevel = rng.randInt(75, 85);
            player.relationships[parent.id] = { level: relLevel, type: 'family' };
            player.familyMembers.push({
                npcId: parent.id,
                role: roles[pi],
                name: parent.firstName + ' ' + parent.lastName
            });
            parentCount++;
        }

        // Clean up temp flags
        for (var cl = 0; cl < potentialParents.length; cl++) {
            delete potentialParents[cl]._familyUsed;
        }

        // Generate siblings (1-3 based on start)
        var numSiblings = startConfig.id === 'very_easy' ? rng.randInt(1, 3) : rng.randInt(1, 2);
        var potentialSiblings = townPeople.filter(function(p) {
            return p.alive && p.age >= 14 && p.age <= 25 && !p.isPlayerFamily && !p.employerId;
        });

        for (var si = 0; si < numSiblings && si < potentialSiblings.length; si++) {
            var sib = potentialSiblings[si];
            sib.isPlayerFamily = true;
            sib.familyRole = 'sibling';

            var sibRole = sib.sex === 'M' ? 'brother' : 'sister';
            var sibRelLevel = rng.randInt(65, 75);
            player.relationships[sib.id] = { level: sibRelLevel, type: 'family' };
            player.familyMembers.push({
                npcId: sib.id,
                role: sibRole,
                name: sib.firstName + ' ' + sib.lastName
            });
        }
    }

    // ── Indentured Servant Start ──
    function initIndenturedStart() {
        var rng = Engine.getRng();
        var people = Engine.getPeople();
        var eliteMerchants = people.filter(function(p) { return p.isEliteMerchant && p.alive; });
        var masterId = eliteMerchants.length > 0 ? rng.pick(eliteMerchants).id : null;

        // Select 8-10 random escape methods from pool of 15
        var pool = CONFIG.INDENTURED_ESCAPE_POOL.slice();
        var numEscapes = rng.randInt(8, 10);
        var selected = [];
        for (var i = 0; i < numEscapes && pool.length > 0; i++) {
            var idx = rng.randInt(0, pool.length - 1);
            selected.push(pool[idx].id);
            pool.splice(idx, 1);
        }

        player.indentured = {
            active: true,
            masterId: masterId,
            startDay: 0,
            contractDays: 2520,
            debtRemaining: 15000,
            discoveredEscapes: [],
            availableEscapes: selected,
            // Master Task System
            currentTask: null,
            taskHistory: [],
            consecutiveFailures: 0,
            totalTasksCompleted: 0,
            totalTasksFailed: 0,
            lastTaskDay: 0,
            nextTaskDay: 15,  // First task after 15 days (settling in period)
            masterRelationship: 50,  // 0-100, affects task rewards and consequences
            masterMood: 'neutral',       // 'kind', 'neutral', 'cruel', 'generous', 'suspicious'
            masterMoodSince: 0,
            earlyReleaseOffered: false
        };

        // Move player to master's town (servant goes where master lives)
        if (masterId) {
            var master = Engine.findPerson(masterId);
            if (master && master.townId) {
                player.townId = master.townId;
                var masterTown = Engine.findTown(master.townId);
                if (masterTown) {
                    player.startingKingdomId = masterTown.kingdomId;
                    Engine.logEvent('⛓️ Your master ' + master.firstName + ' ' + master.lastName + ' has brought you to ' + masterTown.name + ' to begin your servitude.');
                }
            }
        }
    }

    // ── Pilgrim Start ──
    function initPilgrimStart() {
        var rng = Engine.getRng();
        var towns = Engine.getTowns();

        // Mark 5-8 towns as holy sites (spread across kingdoms)
        var numSites = rng.randInt(5, 8);
        var holySiteIds = [];
        var kingdoms = Engine.getKingdoms();
        // Try to spread across kingdoms
        var shuffledTowns = towns.slice().sort(function() { return rng.random() - 0.5; });
        var usedKingdoms = {};
        for (var ti = 0; ti < shuffledTowns.length && holySiteIds.length < numSites; ti++) {
            var t = shuffledTowns[ti];
            // Prefer towns from kingdoms we haven't used yet
            if (!usedKingdoms[t.kingdomId] || holySiteIds.length >= kingdoms.length) {
                t.holySite = true;
                holySiteIds.push(t.id);
                usedKingdoms[t.kingdomId] = true;
            }
        }

        // All 3 goals available — player must complete any 2
        var goals = ['visit_all_sites', 'convert_50_followers', 'build_temple'];

        player.pilgrim = {
            active: true,
            holySites: holySiteIds,
            visitedSites: [],
            followers: 0,
            sermonsGiven: 0,
            conversionAttempts: 0,
            goals: goals,
            followerNpcs: {},
            goalsCompleted: 0,
            templeBuilt: false,
            donations: 0,
            rivalFaith: {
                name: '',
                followers: 0,
                preacherName: '',
                townId: null,
                strength: 10
            },
            rivalDefeated: false
        };

        // Generate rival faith
        var rivalNames = ['The Order of the Eternal Flame', 'The Cult of the Silver Moon', 'The Brotherhood of Iron',
            'The Circle of the Ancient Oak', 'The Disciples of the Storm', 'The Keepers of the Deep',
            'The Seekers of the Void', 'The Children of Dawn'];
        var preacherFirstNames = ['Brother Aldous', 'Sister Miriam', 'Prophet Cassius', 'Elder Theron',
            'Sage Lydia', 'Father Ambrose', 'Mother Elara', 'Deacon Mortis'];
        player.pilgrim.rivalFaith.name = rng.pick(rivalNames);
        player.pilgrim.rivalFaith.preacherName = rng.pick(preacherFirstNames);
        // Rival starts in a random town different from player
        var otherTowns = towns.filter(function(t) { return t.id !== player.townId; });
        if (otherTowns.length > 0) {
            player.pilgrim.rivalFaith.townId = rng.pick(otherTowns).id;
        }
    }

    // ── Shipwrecked Start ──
    function initShipwreckedStart() {
        var rng = Engine.getRng();
        var towns = Engine.getTowns();
        var coastalTowns = towns.filter(function(t) { return t.isPort; });
        if (coastalTowns.length > 0) {
            var coastalTown = rng.pick(coastalTowns);
            player.townId = coastalTown.id;
            player.startingKingdomId = coastalTown.kingdomId;
        }

        // Generate 5 resonance sites in different towns
        var shuffledTowns = towns.slice();
        for (var si = shuffledTowns.length - 1; si > 0; si--) {
            var sj = rng.randInt(0, si);
            var tmp = shuffledTowns[si];
            shuffledTowns[si] = shuffledTowns[sj];
            shuffledTowns[sj] = tmp;
        }
        var resonanceSites = [];
        var siteNames = ['The Sunken Temple', 'The Whispering Stones', 'The Ancient Lighthouse', 'The Forgotten Grotto', 'The Tidal Monolith'];
        var siteVisions = [
            'A great city of white stone rises from the sea. Your homeland... you remember now.',
            'Ships with sails of gold cross an impossibly blue ocean. You were aboard one once.',
            'A council of elders places the artifact in your hands. "Carry it to the new world," they whisper.',
            'Two paths diverge: one leads to a grand embassy, the other to a figure glowing with inner light.',
            'The complete sea chart materializes — a route between two worlds, separated by storm and time.'
        ];
        for (var ri = 0; ri < 5 && ri < shuffledTowns.length; ri++) {
            resonanceSites.push({
                townId: shuffledTowns[ri].id,
                name: siteNames[ri],
                vision: siteVisions[ri],
                visited: false
            });
        }

        player.shipwrecked = {
            active: true,
            languageSkill: 0,
            artifactKept: true,
            storiesTold: 0,
            craftsTaught: 0,
            exoticRecipes: [],
            // Resonance Path
            resonanceSites: resonanceSites,
            resonanceSitesVisited: 0,
            seaChartFragments: 0,
            artifactPulsing: false,
            finalChoiceAvailable: false,
            finalChoice: null, // 'open' or 'seal'
            // Embassy state (if opened)
            embassy: null,
            embassyBankAccount: 0,
            embassyPotionsGenerated: 0,
            lastWarpDay: -9999,
            freePotion: null,
            lastFreePotionDay: -9999,
            // Seal state (if absorbed)
            sealBonuses: null,
            deathReversalAvailable: false,
            deathReversalUsed: false,
            // Homeland NPCs
            homelandNPCs: []
        };

        player.inventory.exotic_artifact = 1;
    }

